             className="p-2 rounded-full bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 transition active:scale-90"
           >
             {theme === ThemeMode.LIGHT ? <Moon size={18} /> : <Sun size={18} />}
           </button>
         </header>
      )}

      {/* Main Content Area */}
      {/* Ajustado pb-24 para pb-32 para dar espaço à navegação com safe-area */}
