import JSZip from 'jszip';
import { Verse } from '../types';
import { BIBLE_BOOKS } from '../constants';

// Helper to remove accents and special chars
const cleanString = (str: string): string => {
  return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
};

// Helper to normalize book names using names and abbreviations
const normalizeBookName = (input: string): string => {
  if (!input) return "Desconhecido";
  const cleaned = cleanString(String(input));

  // 1. Direct match with name
  let match = BIBLE_BOOKS.find(b => cleanString(b.name) === cleaned);
  if (match) return match.name;

  // 2. Match with abbreviations
  match = BIBLE_BOOKS.find(b => b.abbr.some(a => cleanString(a) === cleaned));
  if (match) return match.name;

  // 3. Partial match (contains)
  match = BIBLE_BOOKS.find(b => cleaned.includes(cleanString(b.name)) || cleanString(b.name).includes(cleaned));
  if (match) return match.name;

  return input; // Fallback to input if not found
};

export const processFile = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
  const extension = file.name.split('.').pop()?.toLowerCase();

  try {
    if (extension === 'json') {
      return processJSON(file);
    } else if (extension === 'sqlite' || extension === 'sqlite3') {
      return processSQLite(file);
    } else if (extension === 'zip') {
      return processZip(file);
    } else {
      throw new Error('Formato não suportado. Use .json, .sqlite3 ou .zip');
    }
  } catch (e: any) {
    console.error("Erro no processamento:", e);
    throw new Error(`Falha ao processar arquivo: ${e.message}`);
  }
};

const processJSON = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
  const text = await file.text();
  const data = JSON.parse(text);

  let verses: Verse[] = [];
  let meta = { code: 'IMP', name: file.name.replace('.json', ''), language: 'pt', importedAt: Date.now() };

  // Case 1: Array of verses (Flat)
  if (Array.isArray(data)) {
    verses = data.map((v: any) => ({
      book: normalizeBookName(v.book_name || v.book || v.b),
      chapter: parseInt(v.chapter || v.c),
      verse: parseInt(v.verse || v.v),
      text: v.text || v.t || v.content,
      version: meta.code
    }));
  } 
  // Case 2: Standard Object with metadata
  else if (data.verses && Array.isArray(data.verses)) {
    if (data.metadata) meta = { ...meta, ...data.metadata };
    verses = data.verses.map((v: any) => ({
      book: normalizeBookName(v.book_name || v.book),
      chapter: parseInt(v.chapter),
      verse: parseInt(v.verse),
      text: v.text,
      version: meta.code
    }));
  }
  // Case 3: Hierarchical structure { "Genesis": { "1": { "1": "Text" } } }
  else {
    const books = Object.keys(data);
    for (const bookKey of books) {
      const bookData = data[bookKey];
      if (typeof bookData !== 'object') continue;

      const normalizedBook = normalizeBookName(bookKey);
      const chapters = Object.keys(bookData);

      for (const chapKey of chapters) {
        const chapData = bookData[chapKey];
        if (typeof chapData !== 'object') continue;

        const verseKeys = Object.keys(chapData);
        for (const vKey of verseKeys) {
          verses.push({
            book: normalizedBook,
            chapter: parseInt(chapKey),
            verse: parseInt(vKey),
            text: String(chapData[vKey]),
            version: meta.code
          });
        }
      }
    }
  }

  if (verses.length === 0) throw new Error("Nenhum versículo encontrado no JSON.");
  return { meta, verses };
};

const processSQLite = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
    // @ts-ignore - sql.js loaded via CDN
    if (!window.initSqlJs) throw new Error("Biblioteca SQL.js não carregada.");

    // @ts-ignore
    const SQL = await window.initSqlJs({ locateFile: file => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/${file}` });

    const buffer = await file.arrayBuffer();
    const db = new SQL.Database(new Uint8Array(buffer));

    // Get all tables to find the right one
    const tablesRes = db.exec("SELECT name FROM sqlite_master WHERE type='table'");
    if (tablesRes.length === 0) throw new Error("O banco de dados está vazio.");

    const tableNames = tablesRes[0].values.map(v => String(v[0]));

    // Try to find the most likely table (one that has 'verse', 'bible' or 'text' in name)
    const likelyTable = tableNames.find(t => 
      ['verses', 'bible_verses', 'scripture', 'text', 'data'].includes(t.toLowerCase())
    ) || tableNames[0];

    const stmt = db.prepare(`SELECT * FROM ${likelyTable} LIMIT 100000`); // Safety limit if huge
    const verses: Verse[] = [];

    // Detect column names automatically
    const columnNames = stmt.getColumnNames().map(c => c.toLowerCase());
    const bookCol = columnNames.find(c => ['book', 'book_name', 'b', 'book_id'].includes(c));
    const chapCol = columnNames.find(c => ['chapter', 'c', 'chapter_id', 'chap'].includes(c));
    const verseCol = columnNames.find(c => ['verse', 'v', 'verse_id', 'num'].includes(c));
    const textCol = columnNames.find(c => ['text', 'content', 't', 'scripture'].includes(c));

    if (!textCol || !chapCol || !verseCol) {
      throw new Error(`Colunas não identificadas na tabela ${likelyTable}. Esperado algo como 'text', 'chapter' e 'verse'.`);
    }

    while (stmt.step()) {
        const row = stmt.getAsObject();
        const bookRaw = bookCol ? row[bookCol] : 'Desconhecido';
        const chapter = row[chapCol];
        const verseNum = row[verseCol];
        const text = row[textCol];

        if (chapter && verseNum && text) {
             let finalBook = bookRaw;
             if (typeof bookRaw === 'number' && bookRaw <= 66) {
                 finalBook = BIBLE_BOOKS[bookRaw - 1]?.name;
             }

             verses.push({
                 book: normalizeBookName(String(finalBook)),
                 chapter: Number(chapter),
                 verse: Number(verseNum),
                 text: String(text),
                 version: 'IMP' 
             });
        }
    }
    stmt.free();
    db.close();

    const meta = { 
        code: `IMP-${Math.floor(Math.random() * 9000 + 1000)}`, 
        name: file.name.split('.')[0], 
        language: 'pt', 
        importedAt: Date.now() 
    };

    return { meta, verses: verses.map(v => ({...v, version: meta.code})) };
};

const processZip = async (file: File): Promise<{ meta: any, verses: Verse[] }> => {
    const zip = await JSZip.loadAsync(file);
    const files = Object.values(zip.files) as any[];

    // Look for a .json or .sqlite file inside
    const jsonFile = files.find(f => f.name.toLowerCase().endsWith('.json') && !f.dir);
    if (jsonFile) {
        const text = await jsonFile.async('string');
        const virtualFile = new File([text], jsonFile.name, { type: 'application/json' });
        return processJSON(virtualFile);
    }

    const sqliteFile = files.find(f => (f.name.toLowerCase().endsWith('.sqlite') || f.name.toLowerCase().endsWith('.sqlite3')) && !f.dir);
    if (sqliteFile) {
        const blob = await sqliteFile.async('blob');
        const virtualFile = new File([blob], sqliteFile.name, { type: 'application/x-sqlite3' });
        return processSQLite(virtualFile);
    }

    throw new Error("Nenhum arquivo .json ou .sqlite válido encontrado dentro do ZIP.");
};

import React, { useState, useRef } from 'react';
import { Upload, X, FileType, CheckCircle, AlertCircle, Loader2, Info } from 'lucide-react';
import { processFile } from '../services/importer';
import { saveBibleVersion } from '../services/db';

interface ImportBibleModalProps {
  onClose: () => void;
  onSuccess: () => void;
}

const ImportBibleModal: React.FC<ImportBibleModalProps> = ({ onClose, onSuccess }) => {
  const [dragActive, setDragActive] = useState(false);
  const [file, setFile] = useState<File | null>(null);
  const [status, setStatus] = useState<'idle' | 'processing' | 'saving' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');
  const [stats, setStats] = useState<{ count: number, name: string } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      setFile(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const startImport = async () => {
    if (!file) return;

    try {
      setStatus('processing');
      const { meta, verses } = await processFile(file);

      setStats({ count: verses.length, name: meta.name });
      setStatus('saving');

      await saveBibleVersion(meta, verses);

      setStatus('success');
      setTimeout(() => {
        onSuccess();
        onClose();
      }, 1500);

    } catch (err: any) {
      console.error(err);
      setStatus('error');
      setErrorMessage(err.message || "Erro desconhecido ao importar.");
    }
  };

  const openFileSelector = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black/70 backdrop-blur-md flex items-center justify-center p-4 md:p-6 animate-fade-in overflow-hidden">
      <div className="bg-white dark:bg-navy-800 w-full max-w-md rounded-3xl shadow-2xl border border-gray-200 dark:border-gray-700 relative flex flex-col max-h-[90vh]">

        {/* Header Fixo */}
        <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center bg-white dark:bg-navy-800 rounded-t-3xl">
          <div>
            <h2 className="font-serif text-xl font-bold text-gray-900 dark:text-white">Importar Bíblia</h2>
            <p className="text-[10px] uppercase tracking-widest text-gray-400 font-bold">Arquivos .json, .sqlite3 ou .zip</p>
          </div>
          <button 
            onClick={onClose} 
            className="p-2 bg-gray-100 dark:bg-navy-700 rounded-full text-gray-400 hover:text-gray-600 transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Conteúdo com Scroll se necessário */}
        <div className="p-6 overflow-y-auto custom-scrollbar">
          {status === 'idle' || status === 'error' ? (
            <div className="space-y-6">
              <div 
                className={`border-2 border-dashed rounded-2xl p-10 flex flex-col items-center justify-center text-center transition-all cursor-pointer
                  ${dragActive 
                    ? 'border-petrol-500 bg-petrol-50 dark:bg-petrol-900/20 scale-[1.02]' 
                    : 'border-gray-300 dark:border-gray-600 hover:border-petrol-400 dark:hover:border-petrol-500'}
                  ${file ? 'border-petrol-500 bg-petrol-50/50 dark:bg-petrol-900/10' : ''}
                `}
                onDragEnter={handleDrag}
                onDragLeave={handleDrag}
                onDragOver={handleDrag}
                onDrop={handleDrop}
                onClick={openFileSelector}
              >
