import React, { useState, useEffect } from 'react';
import { Tab, ThemeMode } from './types';
import Navigation from './components/Navigation';
import HomeDashboard from './components/HomeDashboard';
import BibleReader from './components/BibleReader';
import ConfessionsReader from './components/ConfessionsReader';
import StudyDashboard from './components/StudyDashboard';
import Library from './components/Library';
import { Moon, Sun } from 'lucide-react';
import { LOGO_SVG } from './constants';

const App: React.FC = () => {
  const [currentTab, setCurrentTab] = useState<Tab>(Tab.HOME);
  const [theme, setTheme] = useState<ThemeMode>(ThemeMode.LIGHT);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') as ThemeMode;
    if (savedTheme) {
      setTheme(savedTheme);
    } else if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setTheme(ThemeMode.DARK);
    }
  }, []);

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === ThemeMode.DARK) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === ThemeMode.LIGHT ? ThemeMode.DARK : ThemeMode.LIGHT);
  };

  const renderContent = () => {
    switch (currentTab) {
      case Tab.HOME:
        return <HomeDashboard onChangeTab={setCurrentTab} userParams={{ name: 'Peregrino' }} />;
      case Tab.BIBLE:
        return <BibleReader />;
      case Tab.CONFESSIONS:
        return <ConfessionsReader />;
      case Tab.STUDY:
        return <StudyDashboard />;
      case Tab.LIBRARY:
        return <Library />;
      default:
        return <HomeDashboard onChangeTab={setCurrentTab} userParams={{ name: 'Peregrino' }} />;
    }
  };

  return (
    <div className="min-h-screen bg-paper-50 dark:bg-navy-900 flex flex-col max-w-lg mx-auto shadow-2xl overflow-hidden relative border-x border-gray-200 dark:border-gray-800">

      {/* Universal Header with Safe Area support */}
      <header className="px-6 py-3 pt-[calc(env(safe-area-inset-top)+0.75rem)] flex justify-between items-center bg-white dark:bg-navy-900 sticky top-0 z-[60] border-b border-gray-100 dark:border-gray-800">
        <div className="flex items-center gap-3">
          <img src={LOGO_SVG} alt="Logo" className="w-10 h-10 object-contain logo-shadow" />
          <div className="flex flex-col">
            <span className="font-serif text-petrol-700 dark:text-petrol-400 font-bold text-base leading-none tracking-tight">Sola Scriptura</span>
            <span className="text-[9px] uppercase tracking-[0.2em] text-gold-600 font-bold mt-0.5">Confessio</span>
          </div>
        </div>
        <button 
          onClick={toggleTheme}
          className="p-2 rounded-full bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 transition active:scale-90"
        >
          {theme === ThemeMode.LIGHT ? <Moon size={18} /> : <Sun size={18} />}
        </button>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-x-hidden relative h-full">
        <div className={`h-full overflow-y-auto pb-32`}>
          {renderContent()}
        </div>
      </main>

      {/* Bottom Navigation */}
      <Navigation currentTab={currentTab} onTabChange={setCurrentTab} />

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
