                  <p className="text-xs text-gray-400">{highlights.length} versículos</p>
                </div>
              </div>
              <ChevronRight className="text-gray-300 group-hover:text-gold-500 transition-colors" />
            </button>

            <button 
              onClick={() => setView('history')}
              className="bg-white dark:bg-navy-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center justify-between group active:scale-[0.98] transition-all"
            >
              <div className="flex items-center gap-4">
                <div className="p-3 bg-blue-50 dark:bg-blue-900/40 text-blue-600 rounded-xl">
                  <History size={24} />
                </div>
                <div className="text-left">
                  <h3 className="font-bold text-gray-900 dark:text-white">Histórico</h3>
                  <p className="text-xs text-gray-400">{history.length} visitas recentes</p>
                </div>
