import { GoogleGenAI, Type } from "@google/genai";
import { Verse, BibleVersion } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getTheologicalInsight = async (query: string, context: 'biblical' | 'confessional' | 'general' = 'general'): Promise<string> => {
  try {
    const systemPrompt = `
      Você é um assistente teológico especializado na Fé Reformada Clássica.
      Suas respostas devem ser baseadas nas Escrituras Sagradas como norma suprema,
      e subsidiadas pelas Três Formas de Unidade (Confissão Belga, Catecismo de Heidelberg, Cânones de Dort)
      e pelos Padrões de Westminster.

      Mantenha um tom pastoral, acadêmico, porém acessível.
      Responda em Português do Brasil.
      Seja conciso e use formatação Markdown.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        { role: 'user', parts: [{ text: query }] }
      ],
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7,
      }
    });

    return response.text || "Não foi possível gerar uma resposta no momento.";
  } catch (error) {
    console.error("Erro ao consultar Gemini:", error);
    return "Ocorreu um erro ao conectar com o assistente teológico.";
  }
};

export const getBibleChapter = async (book: string, chapter: number, version: BibleVersion): Promise<Verse[]> => {
  // Mapeamento de nomes de versões para instruções mais claras ao modelo
  const versionMap: Record<BibleVersion, string> = {
    'ARA': 'Almeida Revista e Atualizada (Português)',
    'NVT': 'Nova Versão Transformadora (Português)',
    'KJV': 'King James Version (Inglês)',
    'NA28': 'Nestle-Aland 28 (Grego Koiné)',
    'BHS': 'Biblia Hebraica Stuttgartensia (Hebraico)'
  };

  const prompt = `
    Forneça o texto completo da Bíblia para o livro de ${book}, capítulo ${chapter}, usando exatamente a versão "${versionMap[version] || version}".
    Certifique-se de que o texto corresponda fielmente à versão solicitada.
    Se for Grego ou Hebraico, use os caracteres originais.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              verse: { type: Type.INTEGER },
              text: { type: Type.STRING }
            },
            required: ["verse", "text"]
          }
        }
      }
    });

    const jsonText = response.text;
    if (!jsonText) return [];

    const parsedData = JSON.parse(jsonText) as { verse: number, text: string }[];

    return parsedData.map(item => ({
      book,
      chapter,
      verse: item.verse,
      text: item.text,
      version
    }));

  } catch (error) {
    console.error("Erro ao buscar capítulo da Bíblia:", error);
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, MessageSquarePlus, Settings, Book, Heart, Check, X, Loader2, Type, Minus, Plus } from 'lucide-react';
import { MOCK_VERSES, BIBLE_BOOKS } from '../constants';
import { getTheologicalInsight, getBibleChapter } from '../services/geminiService';
import { getStoredChapter, getStoredVersions, StoredBibleMeta, addToHistory, saveHighlight } from '../services/db';
import { BibleVersion, Verse, HistoryEntry, Highlight } from '../types';

const BibleReader: React.FC = () => {
  const [chapter, setChapter] = useState(8);
  const [book, setBook] = useState("Romanos");
  const [fontSize, setFontSize] = useState(18);
  const [showSettings, setShowSettings] = useState(false);
  const [isParallel, setIsParallel] = useState(false);
  const [selectedVerse, setSelectedVerse] = useState<string | null>(null); 
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const [primaryVersion, setPrimaryVersion] = useState<string>('ARA');
  const [secondaryVersion, setSecondaryVersion] = useState<string>('NA28');
  const [favorites, setFavorites] = useState<string[]>([]); 
  const [showVersionSelector, setShowVersionSelector] = useState<'primary' | 'secondary' | null>(null);

  const [customVersions, setCustomVersions] = useState<StoredBibleMeta[]>([]);
  const [primaryContent, setPrimaryContent] = useState<Verse[]>([]);
  const [secondaryContent, setSecondaryContent] = useState<Verse[]>([]);
  const [isLoadingText, setIsLoadingText] = useState(false);

  const [showNav, setShowNav] = useState(false);
  const [navTab, setNavTab] = useState<'AT' | 'NT'>('NT');
  const [selectedBookForNav, setSelectedBookForNav] = useState<string | null>(null);

  // Record History on Book/Chapter change
  useEffect(() => {
    const entry: HistoryEntry = {
      id: `hist-${Date.now()}`,
      type: 'bible',
      reference: `${book} ${chapter}`,
      timestamp: Date.now()
    };
    addToHistory(entry).catch(console.error);
  }, [book, chapter]);

  useEffect(() => {
    getStoredVersions().then(setCustomVersions).catch(console.error);
    const savedSize = localStorage.getItem('bible-font-size');
    if (savedSize) setFontSize(parseInt(savedSize));
  }, []);

  useEffect(() => {
    localStorage.setItem('bible-font-size', fontSize.toString());
  }, [fontSize]);

  useEffect(() => {
    const loadContent = async () => {
      setIsLoadingText(true);

      const fetchVersionText = async (vCode: string): Promise<Verse[]> => {
        const local = MOCK_VERSES.filter(v => v.book === book && v.chapter === chapter && v.version === vCode);
        if (local.length > 0) return local;

        try {
          const stored = await getStoredChapter(vCode, book, chapter);
          if (stored && stored.length > 0) return stored;
        } catch (e) {
          console.error("Erro ao ler do banco local:", e);
        }

        const standardVersions = ['ARA', 'NVT', 'KJV', 'NA28', 'BHS'];
        if (standardVersions.includes(vCode)) {
          return await getBibleChapter(book, chapter, vCode as BibleVersion);
        }

        return [];
      };

      const pText = await fetchVersionText(primaryVersion);
      setPrimaryContent(pText);

      if (isParallel) {
        const sText = await fetchVersionText(secondaryVersion);
        setSecondaryContent(sText);
      }

      setIsLoadingText(false);
    };

    loadContent();
  }, [book, chapter, primaryVersion, secondaryVersion, isParallel]);

  const getVerseKey = (v: { book: string, chapter: number, verse: number }) => `${v.book}-${v.chapter}-${v.verse}`;

  const handleVerseClick = (vKey: string) => {
    setSelectedVerse(selectedVerse === vKey ? null : vKey);
    setAiInsight(null);
  };

  const toggleFavorite = async (v: Verse) => {
    const vKey = getVerseKey(v);
    if (favorites.includes(vKey)) {
       setFavorites(prev => prev.filter(k => k !== vKey));
    } else {
       const hl: Highlight = {
         id: `hl-${Date.now()}`,
         verseKey: vKey,
         text: v.text,
         reference: `${v.book} ${v.chapter}:${v.verse} (${v.version})`,
         createdAt: Date.now()
       };
       await saveHighlight(hl);
       setFavorites(prev => [...prev, vKey]);
    }
  };

  const requestInsight = async (text: string) => {
    setLoadingAi(true);
    const insight = await getTheologicalInsight(
      `Explique teologicamente o versículo: "${text}" à luz da teologia reformada. Se houver termos no original (Grego/Hebraico) relevantes, mencione. Seja breve.`,
      'biblical'
    );
    setAiInsight(insight);
    setLoadingAi(false);
  };

  const handleBookSelect = (bookName: string) => {
    setSelectedBookForNav(bookName);
  };

  const handleChapterSelect = (chap: number) => {
    if (selectedBookForNav) {
      setBook(selectedBookForNav);
      setChapter(chap);
      setShowNav(false);
      setSelectedBookForNav(null);
    }
  };

  const isRTL = (ver: string) => ver === 'BHS';

  const getFontSettings = (ver: string) => {
    if (ver === 'BHS') {
      return { className: 'font-serif leading-loose text-right font-medium tracking-wide', scale: 1.25 };
    }
    if (ver === 'NA28') {
      return { className: 'font-serif leading-relaxed tracking-wide', scale: 1.0 };
    }
    return { className: 'reading-text leading-loose text-left', scale: 1.0 };
  };

  const allAvailableVersions = [
    { code: 'ARA', label: 'Almeida Revista e Atualizada' },
    { code: 'NVT', label: 'Nova Versão Transformadora' },
    { code: 'KJV', label: 'King James Version' },
    { code: 'NA28', label: 'Nestle-Aland 28 (Grego)' },
    { code: 'BHS', label: 'Biblia Hebraica (Hebraico)' },
    ...customVersions.map(cv => ({ code: cv.code, label: cv.name + ' (Importada)' }))
  ];

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 relative">
      {/* Navigation Modal com suporte a Safe Area */}
      {showNav && (
        <div className="absolute inset-0 z-[70] bg-white dark:bg-navy-900 animate-fade-in flex flex-col pt-safe">
          <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-800 flex items-center justify-between bg-white dark:bg-navy-900 sticky top-0">
             {selectedBookForNav ? (
               <button onClick={() => setSelectedBookForNav(null)} className="flex items-center gap-1 text-gray-500 hover:text-petrol-600">
                 <ChevronLeft size={20} /> <span className="text-sm font-bold">Voltar</span>
               </button>
             ) : (
               <h2 className="text-lg font-serif font-bold text-petrol-900 dark:text-white">Navegar</h2>
             )}
             <button onClick={() => { setShowNav(false); setSelectedBookForNav(null); }} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-navy-800 text-gray-500">
               <X size={24} />
             </button>
          </div>
          <div className="flex-1 overflow-y-auto">
            {!selectedBookForNav ? (
              <div className="p-4 pb-32">
                <div className="flex bg-gray-100 dark:bg-navy-800 p-1 rounded-xl mb-6 sticky top-0 z-10">
                  {(['AT', 'NT'] as const).map(tab => (
                    <button
                      key={tab}
                      onClick={() => setNavTab(tab)}
                      className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${
                        navTab === tab 
                          ? 'bg-white dark:bg-navy-700 text-petrol-700 dark:text-white shadow-sm' 
                          : 'text-gray-500 dark:text-gray-400'
                      }`}
                    >
                      {tab === 'AT' ? 'Antigo Testamento' : 'Novo Testamento'}
                    </button>
                  ))}
                </div>
                <div className="grid grid-cols-2 gap-3">
                  {BIBLE_BOOKS.filter(b => b.test === navTab).map(b => (
                    <button 
                      key={b.name}
                      onClick={() => handleBookSelect(b.name)}
                      className="text-left px-4 py-3 rounded-lg hover:bg-petrol-50 dark:hover:bg-navy-800 border border-transparent hover:border-petrol-100 dark:hover:border-navy-700 transition-colors"
                    >
                      <span className="font-serif font-medium text-gray-800 dark:text-gray-200">{b.name}</span>
                    </button>
                  ))}
                </div>
              </div>
            ) : (
              <div className="p-6">
                <h3 className="text-center font-serif text-2xl font-bold text-gray-900 dark:text-white mb-8">
                  {selectedBookForNav}
                </h3>
                <div className="grid grid-cols-5 gap-4">
                   {Array.from({ length: BIBLE_BOOKS.find(b => b.name === selectedBookForNav)?.chapters || 0 }, (_, i) => i + 1).map(chapNum => (
                     <button
                       key={chapNum}
                       onClick={() => handleChapterSelect(chapNum)}
                       className={`aspect-square rounded-full flex items-center justify-center font-medium text-lg transition-all
                         ${(book === selectedBookForNav && chapter === chapNum)
                           ? 'bg-petrol-600 text-white shadow-md' 
                           : 'bg-gray-100 dark:bg-navy-800 text-gray-700 dark:text-gray-300 hover:bg-petrol-100 dark:hover:border-navy-700'
                         }
                       `}
                     >
                       {chapNum}
                     </button>
                   ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Versão Selector com pt-safe adicional */}
      {showVersionSelector && (
        <div className="fixed inset-0 z-[80] bg-black/50 backdrop-blur-sm flex items-start justify-center pt-safe animate-fade-in" onClick={() => setShowVersionSelector(null)}>
          <div className="bg-white dark:bg-navy-800 rounded-3xl shadow-2xl w-full max-w-xs mt-20 max-h-[60vh] overflow-hidden border border-gray-200 dark:border-gray-700 flex flex-col mx-4" onClick={e => e.stopPropagation()}>
            <div className="p-4 bg-petrol-50 dark:bg-navy-900 border-b border-gray-100 dark:border-gray-800">
              <h3 className="text-xs font-bold uppercase tracking-wider text-gray-500">
                Selecionar Versão
              </h3>
            </div>
            <div className="overflow-y-auto flex-1 custom-scrollbar">
              {allAvailableVersions.map(v => (
                <button
                  key={v.code}
                  onClick={() => {
                    if (showVersionSelector === 'primary') setPrimaryVersion(v.code);
                    else setSecondaryVersion(v.code);
                    setShowVersionSelector(null);
                  }}
                  className="w-full text-left px-5 py-4 text-sm hover:bg-gray-50 dark:hover:bg-navy-700 flex items-center justify-between text-gray-800 dark:text-gray-200 border-b border-gray-50 dark:border-gray-800/50"
                >
                  <div className="flex flex-col">
                    <span className="font-bold">{v.code}</span>
                    <span className="text-[10px] text-gray-500">{v.label}</span>
                  </div>
                  {(showVersionSelector === 'primary' ? primaryVersion : secondaryVersion) === v.code && <Check size={16} className="text-petrol-600" />}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Toolbar Interna */}
      <div className="bg-white/95 dark:bg-navy-900/95 backdrop-blur-sm border-b border-gray-200 dark:border-gray-800 px-4 py-3 flex items-center justify-between z-10">
         <div className="flex items-center gap-1">
            <button onClick={() => setChapter(c => Math.max(1, c - 1))} className="p-2 hover:bg-gray-100 dark:hover:bg-navy-800 rounded-full text-gray-400"><ChevronLeft size={18} /></button>
            <div 
              onClick={() => { setShowNav(true); setSelectedBookForNav(null); }}
              className="flex flex-col items-center cursor-pointer px-4 py-1 rounded-xl transition-colors hover:bg-petrol-50 dark:hover:bg-navy-800"
            >
              <span className="font-serif font-bold text-gray-900 dark:text-white flex items-center gap-1 text-sm">
                {book} {chapter}
              </span>
              <div className="flex items-center gap-1 text-[9px] text-gray-400 uppercase font-bold">
                <span onClick={e => { e.stopPropagation(); setShowVersionSelector('primary'); }} className="hover:text-petrol-600 underline decoration-petrol-500/30">{primaryVersion}</span>
                {isParallel && <><span className="opacity-30">|</span> <span onClick={e => { e.stopPropagation(); setShowVersionSelector('secondary'); }} className="hover:text-petrol-600 underline decoration-petrol-500/30">{secondaryVersion}</span></>}
              </div>
            </div>
            <button onClick={() => setChapter(c => c + 1)} className="p-2 hover:bg-gray-100 dark:hover:bg-navy-800 rounded-full text-gray-400"><ChevronRight size={18} /></button>
         </div>
         <div className="flex items-center gap-1">
            <button onClick={() => setIsParallel(!isParallel)} className={`p-2.5 rounded-xl transition-all ${isParallel ? 'bg-petrol-100 text-petrol-700 dark:bg-petrol-900/50 dark:text-petrol-300' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-navy-800'}`}><Book size={18} /></button>
            <button onClick={() => setShowSettings(!showSettings)} className={`p-2.5 rounded-xl transition-all ${showSettings ? 'bg-petrol-100 text-petrol-700 dark:bg-petrol-900/50' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-navy-800'}`}><Settings size={18} /></button>
         </div>
      </div>

      {/* Reader Area */}
      <div className="flex-1 overflow-y-auto p-4 pb-32" onClick={() => setShowSettings(false)}>
        <div className={`mx-auto ${isParallel ? 'w-full max-w-6xl' : 'max-w-2xl'}`}>
          {isLoadingText ? (
            <div className="flex flex-col items-center justify-center py-20 gap-4"><Loader2 size={40} className="text-petrol-600 animate-spin" /><p className="text-sm text-gray-400">Carregando...</p></div>
          ) : (
            <div className="space-y-4">
              {primaryContent.map((verse) => {
                const vKey = getVerseKey(verse);
                const isSelected = selectedVerse === vKey;
                const isFav = favorites.includes(vKey);
                const secondaryVerseText = secondaryContent.find(v => v.verse === verse.verse)?.text;
                const pStyle = getFontSettings(primaryVersion);
                const sStyle = getFontSettings(secondaryVersion);
                return (
                  <div key={vKey} className={`relative rounded-2xl transition-all duration-300 ${isSelected ? 'bg-white dark:bg-navy-800 shadow-xl ring-1 ring-petrol-500/10 p-5 my-4 -mx-2' : 'hover:bg-white/50 dark:hover:bg-white/5'}`}>
                    <div className={`grid ${isParallel ? 'grid-cols-1 md:grid-cols-2 gap-4 md:gap-8' : 'grid-cols-1'}`}>
                       <div className="pl-6 relative">
                         <span className={`text-[10px] font-bold absolute left-0 top-1.5 w-6 text-gray-300 ${isFav ? 'text-gold-500' : ''}`}>{verse.verse}</span>
                         <p onClick={() => handleVerseClick(vKey)} dir={isRTL(primaryVersion) ? "rtl" : "ltr"} className={`${pStyle.className} text-gray-800 dark:text-gray-200 cursor-pointer`} style={{ fontSize: `${fontSize * pStyle.scale}px` }}>{verse.text}</p>
                       </div>
                       {isParallel && (
                         <div className="pl-6 border-t md:border-t-0 md:border-l border-gray-100 dark:border-gray-800 pt-4 md:pt-0">
                            {secondaryVerseText ? (
                              <p onClick={() => handleVerseClick(vKey)} dir={isRTL(secondaryVersion) ? "rtl" : "ltr"} className={`${sStyle.className} text-gray-500 dark:text-gray-400 cursor-pointer italic`} style={{ fontSize: `${fontSize * sStyle.scale}px` }}>{secondaryVerseText}</p>
                            ) : <span className="text-xs text-gray-300 italic">Carregando...</span>}
                         </div>
                       )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

