import React, { useState, useEffect } from 'react';
import { BookMarked, History, Highlighter, Plus, Trash2, X, ChevronRight, UploadCloud, ChevronLeft, MessageSquare, Clock, Scroll, Save, Download, CheckCircle } from 'lucide-react';
import { Note, Highlight, HistoryEntry, ConfessionItem } from '../types';
import { getStoredNotes, getStoredHighlights, getStoredHistory, deleteNote, deleteHighlight, saveNote, saveConfessions, getStoredConfessions } from '../services/db';
import ImportBibleModal from './ImportBibleModal';
import { MOCK_CONFESSIONS } from '../constants';

type ViewMode = 'main' | 'notes' | 'highlights' | 'history';

const Library: React.FC = () => {
  const [view, setView] = useState<ViewMode>('main');
  const [showImportModal, setShowImportModal] = useState(false);
  const [showAddNoteModal, setShowAddNoteModal] = useState(false);
  const [isInstallingDefaults, setIsInstallingDefaults] = useState(false);
  const [installSuccess, setInstallSuccess] = useState(false);

  const [notes, setNotes] = useState<Note[]>([]);
  const [highlights, setHighlights] = useState<Highlight[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [confessionsCount, setConfessionsCount] = useState(0);

  const [newNote, setNewNote] = useState({ title: '', content: '', reference: '' });

  const loadData = async () => {
    const [n, hl, h, c] = await Promise.all([
      getStoredNotes(), 
      getStoredHighlights(), 
      getStoredHistory(),
      getStoredConfessions()
    ]);
    setNotes(n.sort((a, b) => b.createdAt - a.createdAt));
    setHighlights(hl.sort((a, b) => b.createdAt - a.createdAt));
    setHistory(h.sort((a, b) => b.timestamp - a.timestamp));
    setConfessionsCount(c.length);
  };

  useEffect(() => {
    loadData();
  }, [view]);

  const handleInstallDefaults = async () => {
    setIsInstallingDefaults(true);
    try {
      // Aqui simulamos a carga dos documentos padrão (Catecismos)
      // Em uma versão de produção, isso poderia vir de um fetch() de arquivos JSON estáticos
      await saveConfessions(MOCK_CONFESSIONS as ConfessionItem[]);
      setInstallSuccess(true);
      setTimeout(() => setInstallSuccess(false), 3000);
      loadData();
    } catch (e) {
      console.error(e);
    } finally {
      setIsInstallingDefaults(false);
    }
  };

  const handleSaveNote = async () => {
    if (!newNote.title || !newNote.content) return;
    const note: Note = {
      id: `note-${Date.now()}`,
      title: newNote.title,
      content: newNote.content,
      reference: newNote.reference || 'Geral',
      createdAt: Date.now()
    };
    await saveNote(note);
    setNewNote({ title: '', content: '', reference: '' });
    setShowAddNoteModal(false);
    loadData();
  };

  const handleDeleteNote = async (id: string) => {
    await deleteNote(id);
    setNotes(notes.filter(n => n.id !== id));
  };

  const handleDeleteHighlight = async (id: string) => {
    await deleteHighlight(id);
    setHighlights(highlights.filter(h => h.id !== id));
  };

  const renderNotes = () => (
    <div className="animate-fade-in flex flex-col h-full bg-paper-50 dark:bg-navy-900">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <button onClick={() => setView('main')} className="p-2 bg-white dark:bg-navy-800 rounded-full shadow-sm">
            <ChevronLeft size={20} />
          </button>
          <h2 className="font-serif text-2xl font-bold">Anotações</h2>
        </div>
        <button 
          onClick={() => setShowAddNoteModal(true)}
          className="bg-petrol-600 text-white p-2 rounded-full shadow-lg active:scale-95"
        >
          <Plus size={20} />
        </button>
      </div>

      {notes.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-gray-400">
          <MessageSquare size={48} className="mb-4 opacity-20" />
          <p className="text-sm">Nenhuma anotação criada ainda.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {notes.map(note => (
            <div key={note.id} className="bg-white dark:bg-navy-800 p-5 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-sm group">
              <div className="flex justify-between items-start mb-2">
                <span className="text-[10px] font-bold uppercase tracking-widest text-petrol-600 bg-petrol-50 dark:bg-petrol-900/30 px-2 py-0.5 rounded-full">
                  {note.reference}
                </span>
                <button onClick={() => handleDeleteNote(note.id)} className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity p-1">
                  <Trash2 size={16} />
                </button>
              </div>
              <h3 className="font-bold text-gray-900 dark:text-white mb-2">{note.title}</h3>
              <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed font-serif italic">{note.content}</p>
              <div className="mt-3 text-[10px] text-gray-400 flex items-center gap-1">
                <Clock size={10} /> {new Date(note.createdAt).toLocaleDateString()}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderHighlights = () => (
    <div className="animate-fade-in flex flex-col h-full">
      <div className="flex items-center gap-4 mb-6">
        <button onClick={() => setView('main')} className="p-2 bg-white dark:bg-navy-800 rounded-full shadow-sm text-gray-600">
          <ChevronLeft size={20} />
        </button>
        <h2 className="font-serif text-2xl font-bold">Destaques</h2>
      </div>
      {highlights.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-gray-400">
          <Highlighter size={48} className="mb-4 opacity-20" />
          <p className="text-sm">Seus versículos salvos aparecerão aqui.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {highlights.map(hl => (
            <div key={hl.id} className="bg-white dark:bg-navy-800 p-5 rounded-2xl border border-gray-100 dark:border-gray-700 shadow-sm relative group">
              <div className="absolute top-4 left-4 w-1 h-8 bg-gold-500 rounded-full"></div>
              <div className="pl-4">
                <div className="flex justify-between items-start mb-2">
                  <span className="text-[10px] font-bold uppercase tracking-widest text-gold-600">{hl.reference}</span>
                  <button onClick={() => handleDeleteHighlight(hl.id)} className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Trash2 size={16} />
                  </button>
                </div>
                <p className="text-sm text-gray-800 dark:text-gray-200 font-serif leading-relaxed italic">"{hl.text}"</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderHistory = () => (
    <div className="animate-fade-in flex flex-col h-full">
      <div className="flex items-center gap-4 mb-6">
        <button onClick={() => setView('main')} className="p-2 bg-white dark:bg-navy-800 rounded-full shadow-sm text-gray-600">
          <ChevronLeft size={20} />
        </button>
        <h2 className="font-serif text-2xl font-bold">Histórico</h2>
      </div>
      {history.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-gray-400">
          <History size={48} className="mb-4 opacity-20" />
          <p className="text-sm">Seu histórico de leitura está vazio.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {history.map(entry => (
            <div key={entry.id} className="bg-white dark:bg-navy-800 p-4 rounded-xl border border-gray-100 dark:border-gray-700 flex items-center justify-between shadow-sm hover:border-petrol-300 transition-colors cursor-pointer">
              <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${entry.type === 'bible' ? 'bg-petrol-50 text-petrol-600' : 'bg-gold-50 text-gold-600'}`}>
                  {entry.type === 'bible' ? <BookMarked size={16} /> : <Scroll size={16} />}
                </div>
                <div>
                  <div className="text-sm font-bold text-gray-900 dark:text-white">{entry.reference}</div>
                  <div className="text-[10px] text-gray-400">{new Date(entry.timestamp).toLocaleString()}</div>
                </div>
              </div>
              <ChevronRight size={16} className="text-gray-300" />
            </div>
          ))}
        </div>
      )}
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 p-6 pb-24 overflow-y-auto relative">
      {view === 'main' ? (
        <>
          <div className="flex justify-between items-center mb-8">
            <h1 className="font-serif text-2xl font-bold text-petrol-900 dark:text-white">Minha Biblioteca</h1>
            <button 
              onClick={() => setShowImportModal(true)} 
              className="text-petrol-600 dark:text-petrol-400 p-2 hover:bg-petrol-50 dark:hover:bg-navy-800 rounded-full transition-colors flex items-center gap-2"
            >
              <UploadCloud size={24} />
              <span className="text-xs font-bold hidden sm:inline">Importar</span>
            </button>
          </div>

          <div className="grid grid-cols-1 gap-4">
            <button 
              onClick={() => setView('notes')}
              className="bg-white dark:bg-navy-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center justify-between group active:scale-[0.98] transition-all"
            >
              <div className="flex items-center gap-4">
                <div className="p-3 bg-petrol-50 dark:bg-petrol-900/40 text-petrol-600 rounded-xl">
                  <MessageSquare size={24} />
                </div>
                <div className="text-left">
                  <h3 className="font-bold text-gray-900 dark:text-white">Anotações</h3>
                  <p className="text-xs text-gray-400">{notes.length} itens salvos</p>
                </div>
              </div>
              <ChevronRight className="text-gray-300 group-hover:text-petrol-500 transition-colors" />
            </button>

            <button 
              onClick={() => setView('highlights')}
              className="bg-white dark:bg-navy-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center justify-between group active:scale-[0.98] transition-all"
            >
              <div className="flex items-center gap-4">
                <div className="p-3 bg-gold-50 dark:bg-gold-900/40 text-gold-600 rounded-xl">
                  <Highlighter size={24} />
                </div>
                <div className="text-left">
                  <h3 className="font-bold text-gray-900 dark:text-white">Destaques</h3>
                  <p className="text-xs text-gray-400">{highlights.length} versículos</p>
                </div>
              </div>
              <ChevronRight className="text-gray-300 group-hover:text-gold-500 transition-colors" />
            </button>

            <button 
              onClick={() => setView('history')}
              className="bg-white dark:bg-navy-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 flex items-center justify-between group active:scale-[0.98] transition-all"
            >
              <div className="flex items-center gap-4">
                <div className="p-3 bg-blue-50 dark:bg-blue-900/40 text-blue-600 rounded-xl">
                  <History size={24} />
                </div>
                <div className="text-left">
                  <h3 className="font-bold text-gray-900 dark:text-white">Histórico</h3>
                  <p className="text-xs text-gray-400">{history.length} visitas recentes</p>
                </div>
              </div>
              <ChevronRight className="text-gray-300 group-hover:text-blue-500 transition-colors" />
            </button>
          </div>

          {/* Quick Access Documents Section */}
          <div className="mt-10">
            <h2 className="text-xs font-bold uppercase tracking-widest text-gray-400 mb-4">Documentos Padrão</h2>
            <div className="bg-gradient-to-br from-petrol-700 to-petrol-900 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden">
               <div className="relative z-10">
                 <h3 className="text-lg font-serif font-bold mb-2">Padrões Reformados</h3>
                 <p className="text-xs text-white/70 mb-6 leading-relaxed">
                   Instale o Breve Catecismo, o Catecismo Maior de Westminster e o Catecismo Batista para acesso offline completo.
                 </p>
                 <button 
                   onClick={handleInstallDefaults}
                   disabled={isInstallingDefaults || installSuccess}
                   className={`w-full py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
                     installSuccess 
                       ? 'bg-green-500 text-white' 
                       : 'bg-white text-petrol-800 active:scale-95'
                   }`}
                 >
                   {isInstallingDefaults ? (
                     <><Clock size={18} className="animate-spin" /> Instalando...</>
                   ) : installSuccess ? (
                     <><CheckCircle size={18} /> Instalado!</>
                   ) : (
                     <><Download size={18} /> Baixar Padrões</>
                   )}
                 </button>
               </div>
               <Scroll size={120} className="absolute -right-4 -bottom-4 text-white/5 rotate-12" />
            </div>
          </div>
        </>
      ) : (
        <>
          {view === 'notes' && renderNotes()}
          {view === 'highlights' && renderHighlights()}
          {view === 'history' && renderHistory()}
        </>
      )}

      {/* Import Modal */}
      {showImportModal && (
        <ImportBibleModal 
          onClose={() => setShowImportModal(false)} 
          onSuccess={() => { loadData(); setShowImportModal(false); }} 
        />
      )}

      {/* Add Note Modal */}
      {showAddNoteModal && (
        <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white dark:bg-navy-800 w-full max-w-md rounded-3xl shadow-2xl p-6 border border-gray-200 dark:border-gray-700 flex flex-col gap-4 animate-fade-in">
            <div className="flex justify-between items-center">
              <h2 className="text-lg font-bold">Nova Anotação</h2>
              <button onClick={() => setShowAddNoteModal(false)} className="p-1 hover:bg-gray-100 dark:hover:bg-navy-700 rounded-full"><X size={20} /></button>
            </div>
            <input 
              type="text" 
              placeholder="Título" 
              className="w-full bg-gray-50 dark:bg-navy-900 border-none rounded-xl p-4 text-sm focus:ring-2 focus:ring-petrol-500"
              value={newNote.title}
              onChange={e => setNewNote({...newNote, title: e.target.value})}
            />
            <input 
              type="text" 
              placeholder="Referência (ex: Romanos 8:1)" 
              className="w-full bg-gray-50 dark:bg-navy-900 border-none rounded-xl p-4 text-sm focus:ring-2 focus:ring-petrol-500"
              value={newNote.reference}
              onChange={e => setNewNote({...newNote, reference: e.target.value})}
            />
            <textarea 
              placeholder="Conteúdo da anotação..." 
              className="w-full h-32 bg-gray-50 dark:bg-navy-900 border-none rounded-xl p-4 text-sm focus:ring-2 focus:ring-petrol-500 resize-none"
              value={newNote.content}
              onChange={e => setNewNote({...newNote, content: e.target.value})}
            ></textarea>
            <button 
              onClick={handleSaveNote}
              className="w-full bg-petrol-600 text-white py-4 rounded-xl font-bold flex items-center justify-center gap-2 hover:bg-petrol-700 transition-colors"
            >
              <Save size={18} /> Salvar Anotação
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Library;

import React, { useState, useMemo, useEffect } from 'react';
import { Search, Filter, Bookmark, Share2, X, Check, Tag, Loader2, BookOpen } from 'lucide-react';
import { MOCK_CONFESSIONS } from '../constants';
import { addToHistory, getStoredConfessions } from '../services/db';
import { HistoryEntry, ConfessionItem } from '../types';

const ConfessionsReader: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [selectedSources, setSelectedSources] = useState<string[]>([]);
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [confessions, setConfessions] = useState<ConfessionItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const loadConfessions = async () => {
      setIsLoading(true);
      const stored = await getStoredConfessions();
      // Unifica mocks com o que está no banco (preferindo o banco)
      const uniqueItems = Array.from(new Map([...MOCK_CONFESSIONS, ...stored].map(item => [item.id, item])).values());
      setConfessions(uniqueItems as ConfessionItem[]);
      setIsLoading(false);
    };
    loadConfessions();
  }, []);

  const allSources = useMemo(() => Array.from(new Set(confessions.map(c => c.source))), [confessions]);
  const allTags = useMemo(() => Array.from(new Set(confessions.flatMap(c => c.tags))), [confessions]);

  const handleExpand = (item: ConfessionItem) => {
    if (expandedId !== item.id) {
       setExpandedId(item.id);
       const entry: HistoryEntry = {
         id: `hist-${Date.now()}`,
         type: 'confession',
         reference: `${item.source} - ${item.reference}`,
         timestamp: Date.now()
       };
       addToHistory(entry).catch(console.error);
    } else {
       setExpandedId(null);
    }
  };

  const toggleSource = (source: string) => {
    setSelectedSources(prev => prev.includes(source) ? prev.filter(s => s !== source) : [...prev, source]);
  };

  const toggleTag = (tag: string) => {
    setSelectedTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
  };

  const filteredConfessions = confessions.filter(c => {
    const matchesSearch = searchTerm === '' ||
      c.question?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.answer.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.source.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesSource = selectedSources.length === 0 || selectedSources.includes(c.source);
    const matchesTags = selectedTags.length === 0 || c.tags.some(tag => selectedTags.includes(tag));
    return matchesSearch && matchesSource && matchesTags;
  });

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 pb-24">
      <div className="bg-white dark:bg-navy-900 border-b border-gray-100 dark:border-gray-800 p-4 sticky top-0 z-20 shadow-sm">
        <div className="flex justify-between items-center mb-4">
           <h1 className="font-serif text-xl font-bold text-petrol-900 dark:text-white">Confissões</h1>
           {(selectedSources.length > 0 || selectedTags.length > 0) && <button onClick={() => { setSelectedSources([]); setSelectedTags([]); }} className="text-xs font-bold text-petrol-600">Limpar</button>}
        </div>
        <div className="flex gap-2">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
            <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-gray-50 dark:bg-navy-800 rounded-xl py-2.5 pl-10 pr-4 text-sm focus:ring-2 focus:ring-petrol-500 dark:text-white" />
          </div>
          <button onClick={() => setShowFilters(!showFilters)} className={`p-2.5 rounded-xl transition-colors ${showFilters || (selectedSources.length + selectedTags.length > 0) ? 'bg-petrol-100 text-petrol-700' : 'bg-gray-50 dark:bg-navy-800 text-gray-400'}`}><Filter size={18} /></button>
        </div>
        {showFilters && (
          <div className="mt-4 space-y-4 animate-fade-in border-t border-gray-50 dark:border-gray-800 pt-4 max-h-48 overflow-y-auto">
            <div>
              <h3 className="text-[10px] font-bold uppercase text-gray-400 mb-2">Fontes</h3>
              <div className="flex flex-wrap gap-2">{allSources.map(s => <button key={s} onClick={() => toggleSource(s)} className={`px-3 py-1.5 rounded-full text-xs font-medium border ${selectedSources.includes(s) ? 'bg-petrol-600 border-petrol-600 text-white' : 'bg-white dark:bg-navy-900 text-gray-500 border-gray-200'}`}>{s}</button>)}</div>
            </div>
            {allTags.length > 0 && (
              <div>
                <h3 className="text-[10px] font-bold uppercase text-gray-400 mb-2">Assuntos</h3>
                <div className="flex flex-wrap gap-2">{allTags.map(t => <button key={t} onClick={() => toggleTag(t)} className={`px-3 py-1.5 rounded-full text-xs font-medium border ${selectedTags.includes(t) ? 'bg-gold-500 border-gold-500 text-white' : 'bg-white dark:bg-navy-900 text-gray-400 border-gray-200'}`}>{t}</button>)}</div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <Loader2 size={32} className="animate-spin text-petrol-600" />
            <p className="text-sm text-gray-400">Preparando documentos...</p>
          </div>
        ) : filteredConfessions.length === 0 ? (
          <div className="text-center py-20">
             <BookOpen size={48} className="mx-auto text-gray-200 mb-4" />
             <p className="text-gray-400 text-sm">Nenhum documento encontrado.</p>
          </div>
        ) : (
          filteredConfessions.map((item) => {
            const isExpanded = expandedId === item.id;
            return (
              <div key={item.id} className={`bg-white dark:bg-navy-800 rounded-2xl border transition-all overflow-hidden ${isExpanded ? 'border-petrol-500 shadow-xl' : 'border-gray-100 dark:border-gray-800'}`}>
                <div className="p-4 cursor-pointer" onClick={() => handleExpand(item)}>
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-[9px] font-bold uppercase tracking-wider text-gray-400 bg-gray-50 dark:bg-navy-900 px-1.5 py-0.5 rounded-md">{item.source} • {item.reference}</span>
                  </div>
                  <h3 className="font-serif font-bold text-gray-900 dark:text-white leading-tight">{item.question}</h3>
