import React, { useState, useMemo, useEffect } from 'react';
import { Search, Filter, Bookmark, Share2, X, Check, Tag, Loader2, BookOpen, ArrowUpDown, Clock, Zap, HelpCircle, Database, FileJson, ShieldCheck, Plus } from 'lucide-react';
import { MOCK_CONFESSIONS } from '../constants';
import { addToHistory, getStoredConfessions, saveConfessionHighlight, getStoredConfessionHighlights, deleteConfessionHighlight } from '../services/db';
import { HistoryEntry, ConfessionItem, ConfessionHighlight } from '../types';
import ImportBibleModal from './ImportBibleModal';

type SortOption = 'recent' | 'popular' | 'alpha';

const ConfessionsReader: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [sortBy, setSortBy] = useState<SortOption>('popular');
  const [selectedSources, setSelectedSources] = useState<string[]>([]);
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [confessions, setConfessions] = useState<ConfessionItem[]>([]);
  const [savedIds, setSavedIds] = useState<Set<string>>(new Set());
  const [isLoading, setIsLoading] = useState(true);
  const [feedback, setFeedback] = useState<{ id: string, message: string } | null>(null);

  const loadData = async () => {
    setIsLoading(true);
    const [storedConfessions, storedHighlights] = await Promise.all([
      getStoredConfessions(),
      getStoredConfessionHighlights()
    ]);

    const uniqueItems = Array.from(new Map([...MOCK_CONFESSIONS, ...storedConfessions].map(item => [item.id, item])).values());
    setConfessions(uniqueItems as ConfessionItem[]);
    setSavedIds(new Set(storedHighlights.map(h => h.confessionId)));
    setIsLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const allSources = useMemo(() => Array.from(new Set(confessions.map(c => c.source))), [confessions]);
  const allTags = useMemo(() => Array.from(new Set(confessions.flatMap(c => c.tags))), [confessions]);

  const handleExpand = (item: ConfessionItem) => {
    if (expandedId !== item.id) {
       setExpandedId(item.id);
       const entry: HistoryEntry = {
         id: `hist-${Date.now()}`,
         type: 'confession',
         reference: `${item.source} - ${item.reference}`,
         timestamp: Date.now()
       };
       addToHistory(entry).catch(console.error);
    } else {
       setExpandedId(null);
    }
  };

  const toggleFavorite = async (e: React.MouseEvent, item: ConfessionItem) => {
    e.stopPropagation();
    const isSaved = savedIds.has(item.id);

    if (isSaved) {
      const highlights = await getStoredConfessionHighlights();
      const target = highlights.find(h => h.confessionId === item.id);
      if (target) {
        await deleteConfessionHighlight(target.id);
        const newSaved = new Set(savedIds);
        newSaved.delete(item.id);
        setSavedIds(newSaved);
        showFeedback(item.id, 'Removido');
      }
    } else {
      const hl: ConfessionHighlight = {
        id: `ch-${Date.now()}`,
        confessionId: item.id,
        question: item.question || '',
        answer: item.answer,
        source: item.source,
        reference: item.reference,
        createdAt: Date.now()
      };
      await saveConfessionHighlight(hl);
      const newSaved = new Set(savedIds);
      newSaved.add(item.id);
      setSavedIds(newSaved);
      showFeedback(item.id, 'Salvo!');
    }
  };

  const showFeedback = (id: string, message: string) => {
    setFeedback({ id, message });
    setTimeout(() => {
      setFeedback(prev => prev?.id === id ? null : prev);
    }, 2000);
  };

  const toggleSource = (source: string) => {
    setSelectedSources(prev => 
      prev.includes(source) ? prev.filter(s => s !== source) : [...prev, source]
    );
  };

  const toggleTag = (tag: string) => {
    setSelectedTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
  };

  const filteredAndSortedConfessions = useMemo(() => {
    let result = confessions.filter(c => {
      const matchesSearch = searchTerm === '' ||
        c.question?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        c.answer.toLowerCase().includes(searchTerm.toLowerCase()) ||
        c.source.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesSource = selectedSources.length === 0 || selectedSources.includes(c.source);
      const matchesTags = selectedTags.length === 0 || c.tags.some(tag => selectedTags.includes(tag));
      return matchesSearch && matchesSource && matchesTags;
    });

    result.sort((a, b) => {
      if (sortBy === 'recent') return (b.createdAt || 0) - (a.createdAt || 0);
      if (sortBy === 'popular') return (b.popularity || 0) - (a.popularity || 0);
      if (sortBy === 'alpha') return (a.question || '').localeCompare(b.question || '');
      return 0;
    });

    return result;
  }, [confessions, searchTerm, selectedSources, selectedTags, sortBy]);

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 pb-24 relative">
      {/* Help Modal - Android 14 Style */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-md flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowHelp(false)}>
          <div className="bg-white dark:bg-navy-800 w-full max-w-sm rounded-4xl shadow-2xl p-7 border border-gray-200 dark:border-gray-700 overflow-y-auto max-h-[85vh]" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-6">
               <div className="flex items-center gap-2 text-petrol-600">
                 <HelpCircle size={24} />
                 <h2 className="text-xl font-serif font-black">Guia de Dados</h2>
               </div>
               <button onClick={() => setShowHelp(false)} className="p-2 bg-gray-100 dark:bg-navy-700 rounded-full active-ripple"><X size={20}/></button>
            </div>

            <div className="space-y-6">
              <div className="flex gap-4">
                <div className="bg-green-50 dark:bg-green-900/30 text-green-600 p-3 rounded-2xl shrink-0 h-fit">
                  <ShieldCheck size={20} />
                </div>
                <div>
                  <h3 className="font-bold text-sm mb-1 text-gray-900 dark:text-gray-100">Privacidade Local</h3>
                  <p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed">Tudo fica no seu celular. Não usamos servidores externos para suas confissões pessoais.</p>
                </div>
              </div>

              <div className="flex gap-4">
                <div className="bg-blue-50 dark:bg-blue-900/30 text-blue-600 p-3 rounded-2xl shrink-0 h-fit">
                  <FileJson size={20} />
                </div>
                <div>
                  <h3 className="font-bold text-sm mb-1 text-gray-900 dark:text-gray-100">Estrutura JSON</h3>
                  <p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed mb-3">Formato ideal para importação:</p>
                  <pre className="text-[9px] bg-gray-100 dark:bg-navy-950 p-3 rounded-xl overflow-x-auto text-gray-600 dark:text-gray-400 font-mono">
{`[
  {
    "source": "Heidelberg",
    "reference": "P. 1",
    "question": "Seu consolo?",
    "answer": "Cristo...",
    "tags": ["Fé"]
  }
]`}
                  </pre>
                </div>
              </div>
            </div>
            <button onClick={() => setShowHelp(false)} className="w-full mt-8 py-4 bg-petrol-600 text-white rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-lg active-ripple">Entendido</button>
          </div>
        </div>
      )}

      {/* Import Modal */}
      {showImportModal && (
        <ImportBibleModal 
          onClose={() => setShowImportModal(false)} 
          onSuccess={() => loadData()} 
        />
      )}

      {/* Sticky Header */}
      <div className="bg-white/90 dark:bg-navy-900/90 backdrop-blur-xl border-b border-gray-100 dark:border-gray-800 p-4 sticky top-0 z-20 shadow-sm">
        <div className="flex justify-between items-center mb-4">
           <div className="flex items-center gap-2">
              <h1 className="font-serif text-xl font-bold text-petrol-900 dark:text-white">Confissões</h1>
              <button onClick={() => setShowHelp(true)} className="p-1 text-gray-300 hover:text-petrol-500 transition-colors active-ripple"><HelpCircle size={18} /></button>
           </div>
           <div className="flex items-center gap-2">
             <button 
              onClick={() => setShowImportModal(true)}
              className="p-2 bg-petrol-50 dark:bg-navy-800 text-petrol-600 dark:text-petrol-400 rounded-xl active-ripple flex items-center gap-1.5"
             >
               <Plus size={18} />
               <span className="text-[10px] font-black uppercase tracking-widest hidden xs:inline">Importar</span>
             </button>
             {(selectedSources.length > 0 || selectedTags.length > 0 || searchTerm !== '') && (
               <button onClick={() => { setSelectedSources([]); setSelectedTags([]); setSearchTerm(''); }} className="text-[10px] font-black uppercase tracking-widest text-petrol-600 bg-petrol-50 px-2.5 py-1.5 rounded-xl active-ripple">Limpar</button>
             )}
           </div>
        </div>

        <div className="flex gap-2 mb-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
            <input 
              type="text" 
              placeholder="Buscar termo ou fonte..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              className="w-full bg-gray-50 dark:bg-navy-800 rounded-2xl py-3.5 pl-10 pr-4 text-sm focus:ring-2 focus:ring-petrol-500 dark:text-white border-none shadow-inner" 
            />
          </div>
          <button onClick={() => setShowFilters(!showFilters)} className={`p-3.5 rounded-2xl transition-all active-ripple ${showFilters || (selectedTags.length > 0) ? 'bg-petrol-600 text-white shadow-lg' : 'bg-white dark:bg-navy-800 text-gray-400 border border-gray-100 dark:border-gray-700 shadow-sm'}`}><Filter size={18} /></button>
        </div>

        {/* Source Selector Chips */}
        <div className="flex items-center gap-2 overflow-x-auto pb-3 no-scrollbar">
          <button onClick={() => setSelectedSources([])} className={`px-4 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all shrink-0 active-ripple ${selectedSources.length === 0 ? 'bg-petrol-600 text-white shadow-md' : 'bg-gray-50 dark:bg-navy-800 text-gray-500'}`}>Todas</button>
          {allSources.sort().map(source => (
            <button key={source} onClick={() => toggleSource(source)} className={`px-4 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all shrink-0 active-ripple border ${selectedSources.includes(source) ? 'bg-petrol-100 border-petrol-200 text-petrol-700 dark:bg-petrol-900/40 dark:border-petrol-800 dark:text-petrol-300' : 'bg-white dark:bg-navy-800 border-gray-100 dark:border-gray-700 text-gray-500'}`}>{source}</button>
          ))}
        </div>

        {/* Sorting Chips */}
        <div className="flex items-center gap-3 overflow-x-auto pb-1 no-scrollbar pt-2 border-t border-gray-50 dark:border-gray-800/50">
           <span className="text-[9px] font-black uppercase text-gray-400 shrink-0 tracking-tighter">Ordenar:</span>
           <button onClick={() => setSortBy('popular')} className={`flex items-center gap-1.5 text-[10px] font-bold px-3 py-1.5 rounded-full transition-all shrink-0 active-ripple ${sortBy === 'popular' ? 'bg-gold-500 text-white shadow-md' : 'text-gray-500 bg-gray-50 dark:bg-navy-800'}`}><Zap size={10} /> Popular</button>
           <button onClick={() => setSortBy('recent')} className={`flex items-center gap-1.5 text-[10px] font-bold px-3 py-1.5 rounded-full transition-all shrink-0 active-ripple ${sortBy === 'recent' ? 'bg-petrol-600 text-white shadow-md' : 'text-gray-500 bg-gray-50 dark:bg-navy-800'}`}><Clock size={10} /> Recentes</button>
           <button onClick={() => setSortBy('alpha')} className={`flex items-center gap-1.5 text-[10px] font-bold px-3 py-1.5 rounded-full transition-all shrink-0 active-ripple ${sortBy === 'alpha' ? 'bg-navy-800 text-white shadow-md' : 'text-gray-500 bg-gray-50 dark:bg-navy-800'}`}><ArrowUpDown size={10} /> A-Z</button>
        </div>

        {showFilters && (
          <div className="mt-4 space-y-4 animate-fade-in border-t border-gray-50 dark:border-gray-800 pt-4 max-h-[40vh] overflow-y-auto custom-scrollbar">
            {allTags.length > 0 && (
              <div>
                <h3 className="text-[10px] font-black uppercase text-gray-400 mb-3 tracking-widest">Filtrar por Assuntos</h3>
                <div className="flex flex-wrap gap-2">
                  {allTags.map(t => (
                    <button key={t} onClick={() => toggleTag(t)} className={`px-3 py-2 rounded-xl text-xs font-bold border transition-all active-ripple ${selectedTags.includes(t) ? 'bg-gold-500 border-gold-500 text-white shadow-sm' : 'bg-white dark:bg-navy-900 text-gray-500 border-gray-200 dark:border-gray-700'}`}>{t}</button>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 pt-6">
        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4"><Loader2 size={32} className="animate-spin text-petrol-600" /><p className="text-sm text-gray-400 font-bold uppercase tracking-widest">Processando...</p></div>
        ) : filteredAndSortedConfessions.length === 0 ? (
          <div className="text-center py-24 bg-white/50 dark:bg-navy-800/50 rounded-4xl border-2 border-dashed border-gray-200 dark:border-gray-700 mx-4">
             <BookOpen size={48} className="mx-auto text-gray-200 dark:text-gray-700 mb-4" />
             <p className="text-gray-400 dark:text-gray-500 text-sm font-bold">Nenhum resultado para estes filtros.</p>
          </div>
        ) : (
          filteredAndSortedConfessions.map((item) => {
            const isExpanded = expandedId === item.id;
            const isSaved = savedIds.has(item.id);
            const hasFeedback = feedback?.id === item.id;
            return (
              <div key={item.id} className={`bg-white dark:bg-navy-800 rounded-3xl border transition-all duration-300 overflow-hidden relative ${isExpanded ? 'border-petrol-500 shadow-2xl scale-[1.02] z-10' : 'border-gray-100 dark:border-gray-800 shadow-sm'}`}>
                <div className="p-6 cursor-pointer active:bg-gray-50 dark:active:bg-navy-700 transition-colors" onClick={() => handleExpand(item)}>
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-black uppercase tracking-tighter text-white bg-petrol-600 px-2.5 py-1 rounded-lg shadow-sm">{item.source}</span>
                      <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{item.reference}</span>
                    </div>
                    {isSaved && !isExpanded && <Bookmark size={14} className="text-petrol-600 fill-current" />}
                  </div>
                  <h3 className="font-serif font-black text-gray-900 dark:text-white leading-snug text-lg">{item.question}</h3>
                  {!isExpanded && (
                    <div className="mt-4 flex gap-2">
                      {item.tags.slice(0, 2).map(tag => (
                        <span key={tag} className="text-[9px] font-black text-gray-400 border border-gray-100 dark:border-gray-700 px-2 py-0.5 rounded-md uppercase">#{tag}</span>
                      ))}
                    </div>
                  )}
                </div>

                {isExpanded && (
                  <div className="px-6 pb-6 animate-fade-in border-t border-gray-50 dark:border-gray-800/50 mt-1 pt-6">
                    <p className="font-serif text-gray-800 dark:text-gray-200 leading-loose text-justify text-lg italic opacity-95 mb-8">{item.answer}</p>
                    <div className="flex flex-wrap gap-2 mb-8">
                      {item.tags.map(tag => (
                        <div key={tag} className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest text-gold-600 bg-gold-50 dark:bg-gold-900/20 px-3 py-1.5 rounded-full border border-gold-100 dark:border-gold-900/40"><Tag size={10} /> {tag}</div>
                      ))}
                    </div>
                    <div className="flex justify-between items-center pt-6 border-t border-gray-50 dark:border-gray-800">
                      <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{item.popularity && `Popularidade: ${item.popularity}%`}</span>
                      <div className="flex gap-6 relative">
                        {hasFeedback && (
                          <span className="absolute -top-10 left-1/2 -translate-x-1/2 text-[11px] font-black text-petrol-600 animate-bounce bg-white dark:bg-navy-800 px-3 py-1 rounded-full shadow-lg border border-petrol-100 dark:border-petrol-900/50 whitespace-nowrap z-20">{feedback.message}</span>
                        )}
                        <button onClick={(e) => toggleFavorite(e, item)} className={`flex items-center gap-2 text-[11px] font-black uppercase tracking-widest transition-all active-ripple ${isSaved ? 'text-petrol-600' : 'text-gray-400'}`}><Bookmark size={16} className={isSaved ? 'fill-current' : ''} /> {isSaved ? 'Salvo' : 'Salvar'}</button>
                        <button className="flex items-center gap-2 text-[11px] font-black uppercase tracking-widest text-gray-400 active-ripple"><Share2 size={16} /> Enviar</button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default ConfessionsReader;

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, MessageSquarePlus, Settings, Book, Heart, Check, X, Loader2, Type, Minus, Plus, Pencil, Save, MessageSquare } from 'lucide-react';
import { MOCK_VERSES, BIBLE_BOOKS } from '../constants';
import { getTheologicalInsight, getBibleChapter } from '../services/geminiService';
import { getStoredChapter, getStoredVersions, StoredBibleMeta, addToHistory, saveHighlight, getStoredNotes, saveNote, deleteHighlight, getStoredHighlights } from '../services/db';
import { BibleVersion, Verse, HistoryEntry, Highlight, Note } from '../types';

interface BibleReaderProps {
  initialBook?: string;
  initialChapter?: number;
  onNavHandled?: () => void;
}

const BibleReader: React.FC<BibleReaderProps> = ({ initialBook, initialChapter, onNavHandled }) => {
  const [chapter, setChapter] = useState(initialChapter || 8);
  const [book, setBook] = useState(initialBook || "Romanos");
  const [fontSize, setFontSize] = useState(18);
  const [showSettings, setShowSettings] = useState(false);
  const [isParallel, setIsParallel] = useState(false);
  const [selectedVerse, setSelectedVerse] = useState<string | null>(null); 
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const [primaryVersion, setPrimaryVersion] = useState<string>('ARA');
  const [secondaryVersion, setSecondaryVersion] = useState<string>('NA28');
  const [favorites, setFavorites] = useState<string[]>([]); 
  const [allNotes, setAllNotes] = useState<Note[]>([]);
  const [isEditingNote, setIsEditingNote] = useState(false);
  const [currentNoteText, setCurrentNoteText] = useState("");

  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });

  const [showVersionSelector, setShowVersionSelector] = useState<'primary' | 'secondary' | null>(null);
  const [customVersions, setCustomVersions] = useState<StoredBibleMeta[]>([]);
  const [primaryContent, setPrimaryContent] = useState<Verse[]>([]);
  const [secondaryContent, setSecondaryContent] = useState<Verse[]>([]);
  const [isLoadingText, setIsLoadingText] = useState(false);

  const [showNav, setShowNav] = useState(false);
  const [navTab, setNavTab] = useState<'AT' | 'NT'>('NT');
  const [selectedBookForNav, setSelectedBookForNav] = useState<string | null>(null);

  const triggerToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 2500);
  };

  // Handle outside navigation jump
  useEffect(() => {
    if (initialBook && initialChapter) {
      setBook(initialBook);
      setChapter(initialChapter);
      onNavHandled?.();
    }
  }, [initialBook, initialChapter]);

  // Load notes to show indicator
  const loadNotes = async () => {
    const notes = await getStoredNotes();
    setAllNotes(notes);
  };

  // Load favorites
  const loadFavorites = async () => {
    const hl = await getStoredHighlights();
    setFavorites(hl.map(h => h.verseKey));
  };

  useEffect(() => {
    loadNotes();
    loadFavorites();
  }, []);

  // Record History on Book/Chapter change
  useEffect(() => {
    const entry: HistoryEntry = {
      id: `hist-${Date.now()}`,
      type: 'bible',
      reference: `${book} ${chapter}`,
      timestamp: Date.now()
    };
    addToHistory(entry).catch(console.error);
  }, [book, chapter]);

  useEffect(() => {
    getStoredVersions().then(setCustomVersions).catch(console.error);
    const savedSize = localStorage.getItem('bible-font-size');
    if (savedSize) setFontSize(parseInt(savedSize));
  }, []);

  useEffect(() => {
    localStorage.setItem('bible-font-size', fontSize.toString());
  }, [fontSize]);

  useEffect(() => {
    const loadContent = async () => {
      setIsLoadingText(true);

      const fetchVersionText = async (vCode: string): Promise<Verse[]> => {
        const local = MOCK_VERSES.filter(v => v.book === book && v.chapter === chapter && v.version === vCode);
        if (local.length > 0) return local;

        try {
          const stored = await getStoredChapter(vCode, book, chapter);
          if (stored && stored.length > 0) return stored;
        } catch (e) {
          console.error("Erro ao ler do banco local:", e);
        }

        const standardVersions = ['ARA', 'NVT', 'KJV', 'NA28', 'BHS'];
        if (standardVersions.includes(vCode)) {
          return await getBibleChapter(book, chapter, vCode as BibleVersion);
        }

        return [];
      };

      const pText = await fetchVersionText(primaryVersion);
      setPrimaryContent(pText);

      if (isParallel) {
        const sText = await fetchVersionText(secondaryVersion);
        setSecondaryContent(sText);
      }

      setIsLoadingText(false);
    };

    loadContent();
  }, [book, chapter, primaryVersion, secondaryVersion, isParallel]);

  const getVerseKey = (v: { book: string, chapter: number, verse: number }) => `${v.book}-${v.chapter}-${v.verse}`;
  const getVerseReference = (v: Verse) => `${v.book} ${v.chapter}:${v.verse}`;

  const handleVerseClick = (vKey: string, verseObj: Verse) => {
    if (selectedVerse === vKey) {
      setSelectedVerse(null);
      setAiInsight(null);
      setIsEditingNote(false);
    } else {
      setSelectedVerse(vKey);
      setAiInsight(null);
      setIsEditingNote(false);
      // Pre-fill note text if exists
      const ref = getVerseReference(verseObj);
      const existingNote = allNotes.find(n => n.reference === ref);
      setCurrentNoteText(existingNote?.content || "");
    }
  };

  const toggleFavorite = async (v: Verse) => {
    const vKey = getVerseKey(v);
    if (favorites.includes(vKey)) {
       const hl = await getStoredHighlights();
       const target = hl.find(h => h.verseKey === vKey);
       if (target) {
         await deleteHighlight(target.id);
         setFavorites(prev => prev.filter(k => k !== vKey));
         triggerToast("Removido dos favoritos");
       }
    } else {
       const hl: Highlight = {
         id: `hl-${Date.now()}`,
         verseKey: vKey,
         text: v.text,
         reference: `${v.book} ${v.chapter}:${v.verse} (${v.version})`,
         createdAt: Date.now()
       };
       await saveHighlight(hl);
       setFavorites(prev => [...prev, vKey]);
       triggerToast("Versículo favoritado!");
    }
  };

  const handleSavePersonalNote = async (verseObj: Verse) => {
    const ref = getVerseReference(verseObj);
    const existingNote = allNotes.find(n => n.reference === ref);

    const note: Note = {
      id: existingNote?.id || `note-${Date.now()}`,
      title: existingNote?.title || `Nota sobre ${ref}`,
      content: currentNoteText,
      reference: ref,
      createdAt: Date.now()
    };

    await saveNote(note);
    await loadNotes();
    setIsEditingNote(false);
    triggerToast("Anotação salva!");
  };

  const requestInsight = async (text: string) => {
    setLoadingAi(true);
    const insight = await getTheologicalInsight(
      `Explique teologicamente o versículo: "${text}" à luz da teologia reformada. Se houver termos no original (Grego/Hebraico) relevantes, mencione. Seja breve.`,
      'biblical'
    );
    setAiInsight(insight);
    setLoadingAi(false);
  };

  const handleBookSelect = (bookName: string) => {
    setSelectedBookForNav(bookName);
  };

  const handleChapterSelect = (chap: number) => {
    if (selectedBookForNav) {
      setBook(selectedBookForNav);
      setChapter(chap);
      setShowNav(false);
      setSelectedBookForNav(null);
    }
  };

  const isRTL = (ver: string) => ver === 'BHS';

  const getFontSettings = (ver: string) => {
    if (ver === 'BHS') {
      return { className: 'font-serif leading-loose text-right font-medium tracking-wide', scale: 1.25 };
    }
    if (ver === 'NA28') {
      return { className: 'font-serif leading-relaxed tracking-wide', scale: 1.0 };
    }
    return { className: 'reading-text leading-loose text-left', scale: 1.0 };
  };

  const allAvailableVersions = [
    { code: 'ARA', label: 'Almeida Revista e Atualizada' },
    { code: 'NVT', label: 'Nova Versão Transformadora' },
    { code: 'KJV', label: 'King James Version' },
    { code: 'NA28', label: 'Nestle-Aland 28 (Grego)' },
    { code: 'BHS', label: 'Biblia Hebraica (Hebraico)' },
    ...customVersions.map(cv => ({ code: cv.code, label: cv.name + ' (Importada)' }))
  ];

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 relative">
      {/* Toast Feedback - Android 14 Pill style */}
      <div className={`fixed bottom-24 left-1/2 -translate-x-1/2 z-[100] transition-all duration-500 pointer-events-none ${toast.visible ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-4 scale-90'}`}>
        <div className="bg-navy-900/90 dark:bg-petrol-600/90 text-white px-6 py-2.5 rounded-full shadow-2xl backdrop-blur-md border border-white/10 flex items-center gap-3">
          <Check size={16} className="text-petrol-400 dark:text-white" />
          <span className="text-xs font-black uppercase tracking-widest">{toast.message}</span>
        </div>
      </div>

      {/* Navigation Modal com suporte a Safe Area */}
      {showNav && (
        <div className="absolute inset-0 z-[70] bg-white dark:bg-navy-900 animate-fade-in flex flex-col pt-safe">
          <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-800 flex items-center justify-between bg-white dark:bg-navy-900 sticky top-0">
             {selectedBookForNav ? (
               <button onClick={() => setSelectedBookForNav(null)} className="flex items-center gap-1 text-gray-500 hover:text-petrol-600">
                 <ChevronLeft size={20} /> <span className="text-sm font-bold">Voltar</span>
               </button>
             ) : (
               <h2 className="text-lg font-serif font-bold text-petrol-900 dark:text-white">Navegar</h2>
             )}
             <button onClick={() => { setShowNav(false); setSelectedBookForNav(null); }} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-navy-800 text-gray-500">
               <X size={24} />
             </button>
          </div>
          <div className="flex-1 overflow-y-auto">
            {!selectedBookForNav ? (
              <div className="p-4 pb-32">
                <div className="flex bg-gray-100 dark:bg-navy-900 p-1 rounded-xl mb-6 sticky top-0 z-10">
                  {(['AT', 'NT'] as const).map(tab => (
                    <button
                      key={tab}
                      onClick={() => setNavTab(tab)}
                      className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${
                        navTab === tab 
                          ? 'bg-white dark:bg-navy-700 text-petrol-700 dark:text-white shadow-sm' 
                          : 'text-gray-500 dark:text-gray-400'
                      }`}
                    >
                      {tab === 'AT' ? 'Antigo Testamento' : 'Novo Testamento'}
                    </button>
                  ))}
                </div>
                <div className="grid grid-cols-2 gap-3">
                  {BIBLE_BOOKS.filter(b => b.test === navTab).map(b => (
                    <button 
                      key={b.name}
                      onClick={() => handleBookSelect(b.name)}
                      className="text-left px-4 py-3 rounded-lg hover:bg-petrol-50 dark:hover:bg-navy-800 border border-transparent hover:border-petrol-100 dark:hover:border-navy-700 transition-colors"
                    >
                      <span className="font-serif font-medium text-gray-800 dark:text-gray-200">{b.name}</span>
                    </button>
                  ))}
                </div>
              </div>
            ) : (
              <div className="p-6">
                <h3 className="text-center font-serif text-2xl font-bold text-gray-900 dark:text-white mb-8">
                  {selectedBookForNav}
                </h3>
                <div className="grid grid-cols-5 gap-4">
                   {Array.from({ length: BIBLE_BOOKS.find(b => b.name === selectedBookForNav)?.chapters || 0 }, (_, i) => i + 1).map(chapNum => (
                     <button
                       key={chapNum}
                       onClick={() => handleChapterSelect(chapNum)}
                       className={`aspect-square rounded-full flex items-center justify-center font-medium text-lg transition-all
                         ${(book === selectedBookForNav && chapter === chapNum)
                           ? 'bg-petrol-600 text-white shadow-md' 
                           : 'bg-gray-100 dark:bg-navy-800 text-gray-700 dark:text-gray-300 hover:bg-petrol-100 dark:hover:bg-navy-700'
                         }
                       `}
                     >
                       {chapNum}
                     </button>
                   ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Versão Selector com pt-safe adicional */}
      {showVersionSelector && (
        <div className="fixed inset-0 z-[80] bg-black/50 backdrop-blur-sm flex items-start justify-center pt-safe animate-fade-in" onClick={() => setShowVersionSelector(null)}>
          <div className="bg-white dark:bg-navy-800 rounded-3xl shadow-2xl w-full max-w-xs mt-20 max-h-[60vh] overflow-hidden border border-gray-200 dark:border-gray-700 flex flex-col mx-4" onClick={e => e.stopPropagation()}>
            <div className="p-4 bg-petrol-50 dark:bg-navy-900 border-b border-gray-100 dark:border-gray-800">
              <h3 className="text-xs font-bold uppercase tracking-wider text-gray-500">
                Selecionar Versão
              </h3>
            </div>
            <div className="overflow-y-auto flex-1 custom-scrollbar">
              {allAvailableVersions.map(v => (
                <button
                  key={v.code}
                  onClick={() => {
                    if (showVersionSelector === 'primary') setPrimaryVersion(v.code);
                    else setSecondaryVersion(v.code);
                    setShowVersionSelector(null);
                  }}
                  className="w-full text-left px-5 py-4 text-sm hover:bg-gray-50 dark:hover:bg-navy-700 flex items-center justify-between text-gray-800 dark:text-gray-200 border-b border-gray-50 dark:border-gray-800/50"
                >
                  <div className="flex flex-col">
                    <span className="font-bold">{v.code}</span>
                    <span className="text-[10px] text-gray-500">{v.label}</span>
                  </div>
                  {(showVersionSelector === 'primary' ? primaryVersion : secondaryVersion) === v.code && <Check size={16} className="text-petrol-600" />}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Toolbar Interna */}
      <div className="bg-white/95 dark:bg-navy-900/95 backdrop-blur-sm border-b border-gray-200 dark:border-gray-800 px-4 py-3 flex items-center justify-between z-10">
         <div className="flex items-center gap-1">
            <button onClick={() => setChapter(c => Math.max(1, c - 1))} className="p-2 hover:bg-gray-100 dark:hover:bg-navy-800 rounded-full text-gray-400"><ChevronLeft size={18} /></button>
            <div 
              onClick={() => { setShowNav(true); setSelectedBookForNav(null); }}
              className="flex flex-col items-center cursor-pointer px-4 py-1 rounded-xl transition-colors hover:bg-petrol-50 dark:hover:bg-navy-800"
            >
              <span className="font-serif font-bold text-gray-900 dark:text-white flex items-center gap-1 text-sm">
                {book} {chapter}
              </span>
              <div className="flex items-center gap-1 text-[9px] text-gray-400 uppercase font-bold">
                <span onClick={e => { e.stopPropagation(); setShowVersionSelector('primary'); }} className="hover:text-petrol-600 underline decoration-petrol-500/30">{primaryVersion}</span>
                {isParallel && <><span className="opacity-30">|</span> <span onClick={e => { e.stopPropagation(); setShowVersionSelector('secondary'); }} className="hover:text-petrol-600 underline decoration-petrol-500/30">{secondaryVersion}</span></>}
              </div>
            </div>
            <button onClick={() => setChapter(c => c + 1)} className="p-2 hover:bg-gray-100 dark:hover:bg-navy-800 rounded-full text-gray-400"><ChevronRight size={18} /></button>
         </div>
         <div className="flex items-center gap-1">
            <button onClick={() => setIsParallel(!isParallel)} className={`p-2.5 rounded-xl transition-all ${isParallel ? 'bg-petrol-100 text-petrol-700 dark:bg-petrol-900/50 dark:text-petrol-300' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-navy-800'}`}><Book size={18} /></button>
            <button onClick={() => setShowSettings(!showSettings)} className={`p-2.5 rounded-xl transition-all ${showSettings ? 'bg-petrol-100 text-petrol-700 dark:bg-petrol-900/50' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-navy-800'}`}><Settings size={18} /></button>
         </div>
      </div>

      {/* Settings (Font Zoom) */}
      {showSettings && (
        <div className="absolute top-16 right-4 z-40 bg-white dark:bg-navy-800 p-5 rounded-2xl shadow-2xl border border-gray-100 dark:border-gray-700 w-64 animate-fade-in-down">
          <div className="flex justify-between items-center mb-4">
            <h4 className="text-xs font-bold uppercase tracking-widest text-gray-400">Ajustes</h4>
            <button onClick={() => setShowSettings(false)} className="text-gray-400 hover:text-gray-600"><X size={14} /></button>
          </div>
          <div className="space-y-6">
            <div>
              <div className="flex justify-between items-center mb-3">
                 <span className="text-xs font-bold text-gray-600 dark:text-gray-300">Tamanho da Fonte</span>
                 <span className="text-xs font-mono bg-gray-100 dark:bg-navy-900 px-1.5 py-0.5 rounded text-petrol-600">{fontSize}px</span>
              </div>
              <div className="flex items-center gap-3">
                <button onClick={() => setFontSize(Math.max(12, fontSize - 1))} className="p-1.5 bg-gray-50 dark:bg-navy-900 rounded-lg text-gray-500"><Minus size={16} /></button>
                <input type="range" min="12" max="36" value={fontSize} onChange={(e) => setFontSize(parseInt(e.target.value))} className="flex-1 h-1 bg-gray-200 dark:bg-gray-700 rounded-full appearance-none accent-petrol-600" />
                <button onClick={() => setFontSize(Math.min(36, fontSize + 1))} className="p-1.5 bg-gray-50 dark:bg-navy-900 rounded-lg text-gray-500"><Plus size={16} /></button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Reader Area */}
      <div className="flex-1 overflow-y-auto p-4 pb-32" onClick={() => setShowSettings(false)}>
        <div className={`mx-auto ${isParallel ? 'w-full max-w-6xl' : 'max-w-2xl'}`}>
          {isLoadingText ? (
            <div className="flex flex-col items-center justify-center py-20 gap-4"><Loader2 size={40} className="text-petrol-600 animate-spin" /><p className="text-sm text-gray-400">Carregando...</p></div>
          ) : (
            <div className="space-y-4">
              {primaryContent.map((verse) => {
                const vKey = getVerseKey(verse);
                const isSelected = selectedVerse === vKey;
                const isFav = favorites.includes(vKey);
                const secondaryVerseText = secondaryContent.find(v => v.verse === verse.verse)?.text;
                const pStyle = getFontSettings(primaryVersion);
                const sStyle = getFontSettings(secondaryVersion);
                const ref = getVerseReference(verse);
                const hasNote = allNotes.some(n => n.reference === ref);

                return (
                  <div key={vKey} className={`relative rounded-3xl transition-all duration-300 ${isSelected ? 'bg-white dark:bg-navy-800 shadow-2xl ring-1 ring-petrol-500/10 p-6 my-6 -mx-2 z-10' : 'hover:bg-white/50 dark:hover:bg-white/5'}`}>
                    <div className={`grid ${isParallel ? 'grid-cols-1 md:grid-cols-2 gap-4 md:gap-8' : 'grid-cols-1'}`}>
                       <div className="pl-8 relative">
                         <span className={`text-[11px] font-black absolute left-0 top-1.5 w-6 text-gray-300 transition-colors ${isFav ? 'text-gold-500' : ''}`}>{verse.verse}</span>
                         <p onClick={() => handleVerseClick(vKey, verse)} dir={isRTL(primaryVersion) ? "rtl" : "ltr"} className={`${pStyle.className} text-gray-900 dark:text-gray-100 cursor-pointer selection:bg-petrol-500/20`} style={{ fontSize: `${fontSize * pStyle.scale}px` }}>{verse.text}</p>
                         {hasNote && !isSelected && (
                           <div className="absolute right-0 top-0 text-petrol-500 opacity-60">
                             <MessageSquare size={12} fill="currentColor" />
                           </div>
                         )}
                       </div>
                       {isParallel && (
                         <div className="pl-8 border-t md:border-t-0 md:border-l border-gray-100 dark:border-gray-800 pt-4 md:pt-0">
                            {secondaryVerseText ? (
                              <p onClick={() => handleVerseClick(vKey, verse)} dir={isRTL(secondaryVersion) ? "rtl" : "ltr"} className={`${sStyle.className} text-gray-500 dark:text-gray-400 cursor-pointer italic`} style={{ fontSize: `${fontSize * sStyle.scale}px` }}>{secondaryVerseText}</p>
                            ) : <span className="text-xs text-gray-300 italic">Carregando...</span>}
                         </div>
                       )}
                    </div>

                    {/* Verse Toolbar */}
                    {isSelected && (
                      <div className="mt-6 flex flex-wrap gap-3 animate-fade-in pl-8 border-t border-gray-100 dark:border-gray-800 pt-5">
                        <button 
                          onClick={() => toggleFavorite(verse)} 
                          className={`flex items-center gap-2 px-4 py-2 text-[10px] font-black uppercase tracking-widest rounded-full border transition-all active-ripple ${isFav ? 'bg-gold-50 border-gold-200 text-gold-600' : 'bg-white dark:bg-navy-700 border-gray-200 dark:border-gray-600 text-gray-600'}`}
                        >
                          <Heart size={14} fill={isFav ? "currentColor" : "none"} /> {isFav ? 'Salvo' : 'Favoritar'}
                        </button>

                        <button 
                          onClick={() => setIsEditingNote(!isEditingNote)} 
                          className={`flex items-center gap-2 px-4 py-2 text-[10px] font-black uppercase tracking-widest rounded-full border transition-all active-ripple ${hasNote ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white dark:bg-navy-700 border-gray-200 dark:border-gray-600 text-gray-600'}`}
                        >
                          <Pencil size={14} /> {hasNote ? 'Editar Nota' : 'Anotar'}
                        </button>

                        <button 
                          onClick={() => requestInsight(verse.text)} 
                          className="flex items-center gap-2 px-5 py-2.5 bg-petrol-600 text-white text-[10px] font-black uppercase tracking-widest rounded-full shadow-lg shadow-petrol-600/20 hover:bg-petrol-700 active:scale-95 transition-all active-ripple"
                        >
                          <MessageSquarePlus size={14} /> {loadingAi ? 'Analisando...' : 'Insight'}
                        </button>
                      </div>
                    )}

                    {/* Inline Note Editor */}
                    {isSelected && isEditingNote && (
                      <div className="mt-5 ml-8 bg-gray-50 dark:bg-navy-900 rounded-2xl p-4 animate-fade-in border border-blue-100 dark:border-blue-900/30">
                        <div className="flex justify-between items-center mb-3">
                           <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-600 flex items-center gap-2">
                             <Pencil size={12} /> Minha Anotação
                           </h4>
                           <button onClick={() => setIsEditingNote(false)} className="text-gray-400 hover:text-gray-600"><X size={14}/></button>
                        </div>
                        <textarea
                          autoFocus
                          value={currentNoteText}
                          onChange={(e) => setCurrentNoteText(e.target.value)}
                          placeholder="Digite sua reflexão aqui..."
                          className="w-full h-24 bg-transparent border-none focus:ring-0 text-sm font-serif italic text-gray-700 dark:text-gray-300 resize-none no-scrollbar"
                        />
                        <div className="mt-3 flex justify-end">
                           <button 
                             onClick={() => handleSavePersonalNote(verse)}
                             className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white text-[9px] font-black uppercase tracking-widest rounded-xl shadow-md hover:bg-blue-700 transition-colors"
                           >
                             <Save size={14} /> Salvar Nota
                           </button>
                        </div>
                      </div>
                    )}

                    {/* AI Insight view */}
                    {isSelected && aiInsight && (
                       <div className="mt-4 mx-8 p-5 bg-petrol-50 dark:bg-navy-900/50 rounded-2xl text-sm leading-relaxed animate-fade-in border border-petrol-100 dark:border-petrol-900">
                          <h4 className="font-black text-petrol-700 dark:text-petrol-300 mb-3 flex items-center gap-2 text-[10px] uppercase tracking-widest"><MessageSquarePlus size={14} /> Comentário Teológico</h4>
                          <div className="font-serif italic text-gray-700 dark:text-gray-300" dangerouslySetInnerHTML={{ __html: aiInsight.replace(/\n/g, '<br/>') }} />
                       </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default BibleReader;

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, MessageSquarePlus, Settings, Book, Heart, Check, X, Loader2, Type, Minus, Plus, Pencil, Save, MessageSquare, UploadCloud } from 'lucide-react';
import { MOCK_VERSES, BIBLE_BOOKS } from '../constants';
import { getTheologicalInsight, getBibleChapter } from '../services/geminiService';
import { getStoredChapter, getStoredVersions, StoredBibleMeta, addToHistory, saveHighlight, getStoredNotes, saveNote, deleteHighlight, getStoredHighlights } from '../services/db';
import { BibleVersion, Verse, HistoryEntry, Highlight, Note } from '../types';
import ImportBibleModal from './ImportBibleModal';

interface BibleReaderProps {
  initialBook?: string;
  initialChapter?: number;
  onNavHandled?: () => void;
}

const BibleReader: React.FC<BibleReaderProps> = ({ initialBook, initialChapter, onNavHandled }) => {
  const [chapter, setChapter] = useState(initialChapter || 8);
  const [book, setBook] = useState(initialBook || "Romanos");
  const [fontSize, setFontSize] = useState(18);
  const [showSettings, setShowSettings] = useState(false);
  const [isParallel, setIsParallel] = useState(false);
  const [selectedVerse, setSelectedVerse] = useState<string | null>(null); 
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const [primaryVersion, setPrimaryVersion] = useState<string>('ARA');
  const [secondaryVersion, setSecondaryVersion] = useState<string>('NA28');
  const [favorites, setFavorites] = useState<string[]>([]); 
  const [allNotes, setAllNotes] = useState<Note[]>([]);
  const [isEditingNote, setIsEditingNote] = useState(false);
  const [currentNoteText, setCurrentNoteText] = useState("");

  const [toast, setToast] = useState<{ message: string; visible: boolean }>({ message: '', visible: false });

  const [showVersionSelector, setShowVersionSelector] = useState<'primary' | 'secondary' | null>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [customVersions, setCustomVersions] = useState<StoredBibleMeta[]>([]);
  const [primaryContent, setPrimaryContent] = useState<Verse[]>([]);
  const [secondaryContent, setSecondaryContent] = useState<Verse[]>([]);
  const [isLoadingText, setIsLoadingText] = useState(false);

  const [showNav, setShowNav] = useState(false);
  const [navTab, setNavTab] = useState<'AT' | 'NT'>('NT');
  const [selectedBookForNav, setSelectedBookForNav] = useState<string | null>(null);

  const triggerToast = (message: string) => {
    setToast({ message, visible: true });
    setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 2500);
  };

  const refreshVersions = async () => {
    try {
      const versions = await getStoredVersions();
      setCustomVersions(versions);
    } catch (e) {
      console.error("Erro ao carregar versões:", e);
    }
  };

  // Recarregar versões sempre que o seletor for aberto
  useEffect(() => {
    if (showVersionSelector) {
      refreshVersions();
    }
  }, [showVersionSelector]);

  // Handle outside navigation jump
  useEffect(() => {
    if (initialBook && initialChapter) {
      setBook(initialBook);
      setChapter(initialChapter);
      onNavHandled?.();
    }
  }, [initialBook, initialChapter]);

  // Load initial data
  useEffect(() => {
    loadNotes();
    loadFavorites();
    refreshVersions();
  }, []);

  const loadNotes = async () => {
    const notes = await getStoredNotes();
    setAllNotes(notes);
  };

  const loadFavorites = async () => {
    const hl = await getStoredHighlights();
    setFavorites(hl.map(h => h.verseKey));
  };

  // Record History on Book/Chapter change
  useEffect(() => {
    const entry: HistoryEntry = {
      id: `hist-${Date.now()}`,
      type: 'bible',
      reference: `${book} ${chapter}`,
      timestamp: Date.now()
    };
    addToHistory(entry).catch(console.error);
  }, [book, chapter]);

  useEffect(() => {
    const savedSize = localStorage.getItem('bible-font-size');
    if (savedSize) setFontSize(parseInt(savedSize));
  }, []);

  useEffect(() => {
    localStorage.setItem('bible-font-size', fontSize.toString());
  }, [fontSize]);

  useEffect(() => {
    const loadContent = async () => {
      setIsLoadingText(true);

      const fetchVersionText = async (vCode: string): Promise<Verse[]> => {
        const local = MOCK_VERSES.filter(v => v.book === book && v.chapter === chapter && v.version === vCode);
        if (local.length > 0) return local;

        try {
          const stored = await getStoredChapter(vCode, book, chapter);
          if (stored && stored.length > 0) return stored;
        } catch (e) {
          console.error("Erro ao ler do banco local:", e);
        }

        const standardVersions = ['ARA', 'NVT', 'KJV', 'NA28', 'BHS'];
        if (standardVersions.includes(vCode)) {
          return await getBibleChapter(book, chapter, vCode as BibleVersion);
        }

        return [];
      };

      const pText = await fetchVersionText(primaryVersion);
      setPrimaryContent(pText);

      if (isParallel) {
        const sText = await fetchVersionText(secondaryVersion);
        setSecondaryContent(sText);
      }

      setIsLoadingText(false);
    };

    loadContent();
  }, [book, chapter, primaryVersion, secondaryVersion, isParallel]);

  const getVerseKey = (v: { book: string, chapter: number, verse: number }) => `${v.book}-${v.chapter}-${v.verse}`;
  const getVerseReference = (v: Verse) => `${v.book} ${v.chapter}:${v.verse}`;

  const handleVerseClick = (vKey: string, verseObj: Verse) => {
    if (selectedVerse === vKey) {
      setSelectedVerse(null);
      setAiInsight(null);
      setIsEditingNote(false);
    } else {
      setSelectedVerse(vKey);
      setAiInsight(null);
      setIsEditingNote(false);
      const ref = getVerseReference(verseObj);
      const existingNote = allNotes.find(n => n.reference === ref);
      setCurrentNoteText(existingNote?.content || "");
    }
  };

  const toggleFavorite = async (v: Verse) => {
    const vKey = getVerseKey(v);
    if (favorites.includes(vKey)) {
       const hl = await getStoredHighlights();
       const target = hl.find(h => h.verseKey === vKey);
       if (target) {
         await deleteHighlight(target.id);
         setFavorites(prev => prev.filter(k => k !== vKey));
         triggerToast("Removido dos favoritos");
       }
    } else {
       const hl: Highlight = {
         id: `hl-${Date.now()}`,
         verseKey: vKey,
         text: v.text,
         reference: `${v.book} ${v.chapter}:${v.verse} (${v.version})`,
         createdAt: Date.now()
       };
       await saveHighlight(hl);
       setFavorites(prev => [...prev, vKey]);
       triggerToast("Versículo favoritado!");
    }
  };

  const handleSavePersonalNote = async (verseObj: Verse) => {
    const ref = getVerseReference(verseObj);
    const existingNote = allNotes.find(n => n.reference === ref);

    const note: Note = {
      id: existingNote?.id || `note-${Date.now()}`,
      title: existingNote?.title || `Nota sobre ${ref}`,
      content: currentNoteText,
      reference: ref,
      createdAt: Date.now()
    };

    await saveNote(note);
    await loadNotes();
    setIsEditingNote(false);
    triggerToast("Anotação salva!");
  };

  const requestInsight = async (text: string) => {
    setLoadingAi(true);
    const insight = await getTheologicalInsight(
      `Explique teologicamente o versículo: "${text}" à luz da teologia reformada. Se houver termos no original (Grego/Hebraico) relevantes, mencione. Seja breve.`,
      'biblical'
    );
    setAiInsight(insight);
    setLoadingAi(false);
  };

  const handleBookSelect = (bookName: string) => {
    setSelectedBookForNav(bookName);
  };

  const handleChapterSelect = (chap: number) => {
    if (selectedBookForNav) {
      setBook(selectedBookForNav);
      setChapter(chap);
      setShowNav(false);
      setSelectedBookForNav(null);
    }
  };

  const isRTL = (ver: string) => ver === 'BHS';

  const getFontSettings = (ver: string) => {
    if (ver === 'BHS') {
      return { className: 'font-serif leading-loose text-right font-medium tracking-wide', scale: 1.25 };
    }
    if (ver === 'NA28') {
      return { className: 'font-serif leading-relaxed tracking-wide', scale: 1.0 };
    }
    return { className: 'reading-text leading-loose text-left', scale: 1.0 };
  };

  const allAvailableVersions = [
    { code: 'ARA', label: 'Almeida Revista e Atualizada', type: 'system' },
    { code: 'NVT', label: 'Nova Versão Transformadora', type: 'system' },
    { code: 'KJV', label: 'King James Version', type: 'system' },
    { code: 'NA28', label: 'Nestle-Aland 28 (Grego)', type: 'system' },
    { code: 'BHS', label: 'Biblia Hebraica (Hebraico)', type: 'system' },
    ...customVersions.map(cv => ({ code: cv.code, label: cv.name, type: 'custom' }))
  ];

  return (
    <div className="flex flex-col h-full bg-paper-50 dark:bg-navy-900 relative">
      {/* Toast Feedback */}
      <div className={`fixed bottom-24 left-1/2 -translate-x-1/2 z-[100] transition-all duration-500 pointer-events-none ${toast.visible ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-4 scale-90'}`}>
        <div className="bg-navy-900/90 dark:bg-petrol-600/90 text-white px-6 py-2.5 rounded-full shadow-2xl backdrop-blur-md border border-white/10 flex items-center gap-3">
          <Check size={16} className="text-petrol-400 dark:text-white" />
          <span className="text-xs font-black uppercase tracking-widest">{toast.message}</span>
        </div>
      </div>

      {/* Import Modal Shortcut */}
      {showImportModal && (
        <ImportBibleModal 
          onClose={() => setShowImportModal(false)} 
          onSuccess={() => { refreshVersions(); setShowVersionSelector(null); triggerToast("Nova versão disponível!"); }} 
        />
      )}

      {/* Navigation Modal */}
      {showNav && (
        <div className="absolute inset-0 z-[70] bg-white dark:bg-navy-900 animate-fade-in flex flex-col pt-safe">
          <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-800 flex items-center justify-between bg-white dark:bg-navy-900 sticky top-0">
             {selectedBookForNav ? (
               <button onClick={() => setSelectedBookForNav(null)} className="flex items-center gap-1 text-gray-500 hover:text-petrol-600">
                 <ChevronLeft size={20} /> <span className="text-sm font-bold">Voltar</span>
               </button>
             ) : (
               <h2 className="text-lg font-serif font-bold text-petrol-900 dark:text-white">Navegar</h2>
             )}
             <button onClick={() => { setShowNav(false); setSelectedBookForNav(null); }} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-navy-800 text-gray-500">
               <X size={24} />
