export const saveBibleVersion = async (meta: StoredBibleMeta, verses: Verse[]): Promise<void> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_VERSES, STORE_META], 'readwrite');
    const metaStore = transaction.objectStore(STORE_META);
    metaStore.put(meta);
    const verseStore = transaction.objectStore(STORE_VERSES);
    verses.forEach(v => {
      const id = `${meta.code}-${v.book}-${v.chapter}-${v.verse}`;
      verseStore.put({ ...v, id, version: meta.code });
    });
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject('Erro ao salvar Bíblia');
  });
};

export const saveConfessions = async (items: ConfessionItem[]): Promise<void> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_CONFESSIONS], 'readwrite');
    const store = transaction.objectStore(STORE_CONFESSIONS);
    items.forEach(item => store.put(item));
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject('Erro ao salvar Confissões');
  });
};

export const addToHistory = (entry: HistoryEntry) => putInStore(STORE_HISTORY, entry);
export const updateStudyProgress = (planId: string, sessionIds: string[]) => putInStore(STORE_STUDY_PROGRESS, { id: planId, completedSessionIds: sessionIds });
export const getStudyProgress = async (planId: string): Promise<string[]> => {
  const db = await initDB();
  return new Promise((resolve) => {
    const transaction = db.transaction([STORE_STUDY_PROGRESS], 'readonly');
    const store = transaction.objectStore(STORE_STUDY_PROGRESS);
    const request = store.get(planId);
    request.onsuccess = () => resolve(request.result?.completedSessionIds || []);
    request.onerror = () => resolve([]);
  });
};

export const getStoredChapter = async (version: string, book: string, chapter: number): Promise<Verse[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_VERSES], 'readonly');
    const store = transaction.objectStore(STORE_VERSES);
    const index = store.index('locator');
    const request = index.getAll([version, book, chapter]);
    request.onsuccess = () => resolve((request.result as Verse[]).sort((a, b) => a.verse - b.verse));
    request.onerror = () => reject(request.error);
  });
};

import JSZip from 'jszip';
import { Verse, ConfessionItem, DictionaryEntry } from '../types';
import { BIBLE_BOOKS } from '../constants';

const cleanString = (str: string): string => {
  return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
};

const normalizeBookName = (input: string): string => {
  if (!input) return "Desconhecido";
  const cleaned = cleanString(String(input));
  let match = BIBLE_BOOKS.find(b => cleanString(b.name) === cleaned);
  if (match) return match.name;
  match = BIBLE_BOOKS.find(b => b.abbr.some(a => cleanString(a) === cleaned));
  if (match) return match.name;
  match = BIBLE_BOOKS.find(b => cleaned.includes(cleanString(b.name)) || cleanString(b.name).includes(cleaned));
  if (match) return match.name;
  return input;
};

export const processFile = async (file: File, type: 'bible' | 'confession' | 'dictionary'): Promise<{ meta?: any, data: any[] }> => {
  if (!file || file.size === 0) throw new Error('Arquivo inválido ou vazio.');
  const extension = file.name.split('.').pop()?.toLowerCase();

  if (type === 'confession') {
    if (extension !== 'json') throw new Error('Confissões devem estar em formato .json');
    return processConfessionJSON(file);
  }

  if (type === 'dictionary') {
    if (extension !== 'json') throw new Error('Dicionários devem estar em formato .json');
    return processDictionaryJSON(file);
  }

  try {
    if (extension === 'json') return processJSON(file);
    if (extension === 'sqlite' || extension === 'sqlite3') return processSQLite(file);
    if (extension === 'zip') return processZip(file);
    throw new Error('Formato não suportado para Bíblia.');
  } catch (e: any) {
    throw new Error(`Falha no processamento: ${e.message}`);
  }
};

const processDictionaryJSON = async (file: File): Promise<{ data: DictionaryEntry[] }> => {
  const text = await file.text();
  const data = JSON.parse(text);
  const items = Array.isArray(data) ? data : (data.entries || []);

  const processed = items.map((item: any, idx: number) => ({
    id: `dict-${Date.now()}-${idx}`,
    word: item.word || item.termo || "Sem título",
    definition: item.definition || item.definicao || item.text || "",
    source: item.source || file.name,
    category: item.category
  }));

  return { data: processed };
};

const processConfessionJSON = async (file: File): Promise<{ data: ConfessionItem[] }> => {
  const text = await file.text();
  const data = JSON.parse(text);
  const items = Array.isArray(data) ? data : (data.items || []);
  if (items.length === 0) throw new Error("Nenhum item de confissão encontrado no JSON.");

  const processed = items.map((item: any, idx: number) => ({
    id: item.id || `conf-${Date.now()}-${idx}`,
    source: item.source || "Fonte Desconhecida",
    reference: item.reference || `Ref ${idx + 1}`,
    question: item.question || item.q,
    answer: item.answer || item.a || item.text,
    tags: Array.isArray(item.tags) ? item.tags : []
  }));

  return { data: processed };
};

const processJSON = async (file: File) => {
  const text = await file.text();
  const data = JSON.parse(text);
  let verses: Verse[] = [];
  let meta = { code: 'IMP', name: file.name.replace('.json', ''), language: 'pt', importedAt: Date.now() };

  if (Array.isArray(data)) {
    verses = data.map((v: any) => ({
      book: normalizeBookName(v.book_name || v.book || v.b),
      chapter: parseInt(v.chapter || v.c),
      verse: parseInt(v.verse || v.v),
      text: v.text || v.t || v.content,
      version: meta.code
    }));
  } else if (data.verses && Array.isArray(data.verses)) {
    if (data.metadata) meta = { ...meta, ...data.metadata };
    verses = data.verses.map((v: any) => ({
      book: normalizeBookName(v.book_name || v.book),
      chapter: parseInt(v.chapter),
      verse: parseInt(v.verse),
      text: v.text,
      version: meta.code
    }));
  } else {
    const books = Object.keys(data);
    for (const bookKey of books) {
      const bookData = data[bookKey];
      if (typeof bookData !== 'object') continue;
      const normalizedBook = normalizeBookName(bookKey);
      for (const chapKey of Object.keys(bookData)) {
        const chapData = bookData[chapKey];
        if (typeof chapData !== 'object') continue;
        for (const vKey of Object.keys(chapData)) {
          verses.push({
            book: normalizedBook,
            chapter: parseInt(chapKey),
            verse: parseInt(vKey),
            text: String(chapData[vKey]),
            version: meta.code
          });
        }
      }
    }
  }
  return { meta, data: verses };
};

const processSQLite = async (file: File) => {
    // @ts-ignore
    const SQL = await window.initSqlJs({ locateFile: f => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/${f}` });
    const buffer = await file.arrayBuffer();
    const db = new SQL.Database(new Uint8Array(buffer));
    const tablesRes = db.exec("SELECT name FROM sqlite_master WHERE type='table'");
    const tableNames = tablesRes[0].values.map(v => String(v[0]));
    const likelyTable = tableNames.find(t => ['verses', 'bible_verses', 'scripture', 'text'].includes(t.toLowerCase())) || tableNames[0];
    const stmt = db.prepare(`SELECT * FROM ${likelyTable} LIMIT 100000`);
    const verses: Verse[] = [];
    const columnNames = stmt.getColumnNames().map(c => c.toLowerCase());
    const bookCol = columnNames.find(c => ['book', 'book_name', 'b'].includes(c));
    const chapCol = columnNames.find(c => ['chapter', 'c', 'chap'].includes(c));
    const verseCol = columnNames.find(c => ['verse', 'v', 'num'].includes(c));
    const textCol = columnNames.find(c => ['text', 'content', 't'].includes(c));
    while (stmt.step()) {
        const row = stmt.getAsObject();
        verses.push({
            book: normalizeBookName(String(bookCol ? row[bookCol] : 'Desconhecido')),
            chapter: Number(row[chapCol!] || 0),
            verse: Number(row[verseCol!] || 0),
            text: String(row[textCol!] || ''),
            version: 'IMP' 
        });
    }
    stmt.free(); db.close();
    const meta = { code: `IMP-${Date.now().toString().slice(-4)}`, name: file.name.split('.')[0], importedAt: Date.now() };
    return { meta, data: verses.map(v => ({...v, version: meta.code})) };
};

const processZip = async (file: File) => {
    const zip = await JSZip.loadAsync(file);
    const files = Object.values(zip.files) as any[];
    const jsonFile = files.find(f => f.name.toLowerCase().endsWith('.json') && !f.dir);
    if (jsonFile) return processJSON(new File([await jsonFile.async('string')], jsonFile.name));
    const sqliteFile = files.find(f => (f.name.toLowerCase().endsWith('.sqlite') || f.name.toLowerCase().endsWith('.sqlite3')) && !f.dir);
    if (sqliteFile) return processSQLite(new File([await sqliteFile.async('blob')], sqliteFile.name));
    throw new Error("Conteúdo ZIP inválido.");
};

import React, { useState, useRef } from 'react';
