                       <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed italic">{entry.definition}</p>
                       <div className="mt-3 text-[9px] font-black uppercase tracking-widest text-gray-400">{entry.source}</div>
                    </div>
