                    {isSelected && aiInsight && (
                       <div className="mt-4 mx-8 p-5 bg-petrol-50 dark:bg-navy-900/50 rounded-3xl text-sm leading-relaxed animate-fade-in border border-petrol-100 dark:border-petrol-900">
