            </div>
          )}
        </div>
      </div>

      {showImportModal && (
        <ImportBibleModal 
          onClose={() => setShowImportModal(false)} 
          onSuccess={() => {
            refreshVersions();
            triggerToast("Bíblia importada com sucesso!");
          }} 
        />
      )}
    </div>
  );
};

