const processJSON = async (file: File) => {
  const text = await file.text();
  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    throw new Error("O arquivo não é um JSON válido.");
  }

  let verses: Verse[] = [];
  let meta = { 
    code: 'IMP-' + Math.random().toString(36).substring(7).toUpperCase(), 
    name: file.name.replace('.json', ''), 
    language: 'pt', 
    importedAt: Date.now() 
  };

  if (data.metadata) {
    meta = { ...meta, ...data.metadata };
  }

  const list = Array.isArray(data) ? data : (data.verses || data.data || data.list || []);
  if (list.length > 0) {
    verses = list.map((v: any) => ({
      book: normalizeBookName(v.book_name || v.book || v.b || v.livro),
      chapter: parseInt(v.chapter || v.c || v.capitulo || 0),
      verse: parseInt(v.verse || v.v || v.versiculo || 0),
      text: String(v.text || v.t || v.content || v.texto || ""),
      version: meta.code
    }));
  } 
  else if (typeof data === 'object') {
    const books = Object.keys(data).filter(k => k !== 'metadata' && k !== 'info');
    for (const bookKey of books) {
      const bookData = data[bookKey];
      if (typeof bookData !== 'object') continue;

      const normalizedBook = normalizeBookName(bookKey);
      for (const chapKey of Object.keys(bookData)) {
        const chapData = bookData[chapKey];
        if (typeof chapData !== 'object') {
           verses.push({
             book: normalizedBook,
             chapter: parseInt(chapKey),
             verse: 1,
             text: String(chapData),
             version: meta.code
           });
           continue;
        }
        for (const vKey of Object.keys(chapData)) {
          verses.push({
            book: normalizedBook,
            chapter: parseInt(chapKey),
            verse: parseInt(vKey),
            text: String(chapData[vKey]),
            version: meta.code
          });
        }
      }
    }
  }

  if (verses.length === 0) {
    throw new Error("Não foi possível identificar a estrutura de versículos no JSON.");
  }

  return { meta, data: verses };
};

const processSQLite = async (file: File) => {
    // @ts-ignore
    const initSql = window.initSqlJs || (window as any).SQL?.initSqlJs;
    if (!initSql) throw new Error("Biblioteca SQL.js não carregada corretamente.");

    const SQL = await initSql({ locateFile: f => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/${f}` });
    const buffer = await file.arrayBuffer();
    const db = new SQL.Database(new Uint8Array(buffer));

    const tablesRes = db.exec("SELECT name FROM sqlite_master WHERE type='table'");
    if (tablesRes.length === 0) throw new Error("Banco de dados SQLite vazio.");

    const tableNames = tablesRes[0].values.map(v => String(v[0]));
    const likelyTable = tableNames.find(t => ['verses', 'bible_verses', 'scripture', 'text', 'bible'].includes(t.toLowerCase())) || tableNames[0];

    const stmt = db.prepare(`SELECT * FROM ${likelyTable} LIMIT 100000`);
    const verses: Verse[] = [];
    const columnNames = stmt.getColumnNames().map(c => c.toLowerCase());

    const bookCol = columnNames.find(c => ['book', 'book_name', 'b', 'book_number', 'livro'].includes(c));
    const chapCol = columnNames.find(c => ['chapter', 'c', 'chap', 'chapter_number', 'capitulo'].includes(c));
    const verseCol = columnNames.find(c => ['verse', 'v', 'num', 'verse_number', 'versiculo'].includes(c));
    const textCol = columnNames.find(c => ['text', 'content', 't', 'texto'].includes(c));

    if (!textCol || !chapCol || !verseCol) {
      throw new Error("Colunas essenciais (capítulo, versículo ou texto) não encontradas no SQLite.");
    }

    while (stmt.step()) {
        const row = stmt.getAsObject();
        verses.push({
            book: normalizeBookName(String(bookCol ? row[bookCol] : 'Desconhecido')),
            chapter: Number(row[chapCol] || 0),
            verse: Number(row[verseCol] || 0),
            text: String(row[textCol] || ''),
            version: 'IMP' 
        });
    }
    stmt.free(); db.close();

    const meta = { 
      code: `SQ-${Date.now().toString().slice(-4)}`, 
      name: file.name.split('.')[0], 
      importedAt: Date.now(),
      language: 'pt'
    };

    return { meta, data: verses.map(v => ({...v, version: meta.code})) };
};

const processZip = async (file: File) => {
    // Uso do construtor new JSZip() para maior compatibilidade ESM
    const zip = await new JSZip().loadAsync(file);
    const files = Object.values(zip.files) as any[];

    const jsonFile = files.find(f => f.name.toLowerCase().endsWith('.json') && !f.dir);
    if (jsonFile) return processJSON(new File([await jsonFile.async('string')], jsonFile.name));

    const sqliteFile = files.find(f => (f.name.toLowerCase().endsWith('.sqlite') || f.name.toLowerCase().endsWith('.sqlite3')) && !f.dir);
    if (sqliteFile) return processSQLite(new File([await sqliteFile.async('blob')], sqliteFile.name));

    throw new Error("Arquivo ZIP não contém arquivos reconhecíveis.");
};

import JSZip from 'jszip';
import { Verse, ConfessionItem, DictionaryEntry } from '../types';
import { BIBLE_BOOKS } from '../constants';

const cleanString = (str: string): string => {
  if (!str) return "";
  return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
};

const normalizeBookName = (input: string): string => {
  if (!input) return "Desconhecido";
  const cleaned = cleanString(String(input));
  let match = BIBLE_BOOKS.find(b => cleanString(b.name) === cleaned);
  if (match) return match.name;
  match = BIBLE_BOOKS.find(b => b.abbr.some(a => cleanString(a) === cleaned));
  if (match) return match.name;
  return input.charAt(0).toUpperCase() + input.slice(1);
};

export const processFile = async (file: File, type: 'bible' | 'confession' | 'dictionary'): Promise<{ meta?: any, data: any[] }> => {
  if (!file || file.size === 0) throw new Error('Arquivo inválido ou vazio.');
  const extension = file.name.split('.').pop()?.toLowerCase();

  try {
    if (type === 'confession') return await processConfessionJSON(file);
    if (type === 'dictionary') return await processDictionaryJSON(file);
    if (extension === 'json') return await processJSON(file);
    if (extension === 'sqlite' || extension === 'sqlite3') return await processSQLite(file);
    if (extension === 'zip') return await processZip(file);
    throw new Error(`Formato .${extension} não suportado.`);
  } catch (e: any) {
    console.error("Erro no processamento:", e);
    throw new Error(e.message || "Erro desconhecido ao processar arquivo.");
  }
};

